	public function getChartOutQuartTOTAL()
		{
			foreach ($this->getMaxYear() as $row) :
				$max_year = $row['max_year'];
			endforeach;

			if (isset($_POST['tahun']))
			{
				$tahun = $_POST['tahun'];
			}else
			{
				$tahun = $max_year;
			}

			$str_sql = "select 'TOTAL' as channel, year(a.tanggal) as on_year, quarter(a.tanggal) as quartal,";
			$str_sql = $str_sql . " sum(a.qty) as qty";
			$str_sql = $str_sql . " from selling_out a";
			$str_sql = $str_sql . " inner join channel b on a.outlet_type = b.outlet_type";
			$str_sql = $str_sql . " where a.item_name <> 42 and year(a.tanggal) = " . $tahun . "";
			$str_sql = $str_sql . " group by on_year, quartal";
			$str_sql = $str_sql . " order by on_year, quartal";

			////Flasher::setMessage('Berhasil',$str_sql,'success');
			$this->db->opendb();
			$this->db->query($str_sql);
			return $this->db->resultSet();
		}

	public function getReportYear()
	{
		$this->db->opendb();
		$this->db->query("select year from " . $this->table_year . "");
		return $this->db->single();
	}

	public function getPeriod_SI()
	{
		$str_sql = "select min(month(tanggal)) as from_month, max(month(tanggal)) as to_month, year(tanggal) as year";
		$str_sql = $str_sql . " from selling_in";
		$str_sql = $str_sql . " where year(tanggal) = (select year from report_year)";

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->single();
	}

