	public function getChart_SO_dist($year)
	{
		$str_sql = "select a.area, a.qty_actual, ifnull(b.qty_target, 0) as qty_target, a.value_actual, ifnull(b.value_target, 0) as value_target from";
		$str_sql = $str_sql . " (select coalesce(b.area, 'TOTAL') as area, sum(a.qty) as qty_actual, sum(a.value_exc)/1000 as value_actual";
		$str_sql = $str_sql . " from selling_out a";
		$str_sql = $str_sql . " inner join area b on a.area = b.area";
		$str_sql = $str_sql . " where year(a.tanggal) = '" . $year . "' and a.area not in ('NSQ DIST ONLINE')";
		$str_sql = $str_sql . " group by b.area asc with rollup) a";
		$str_sql = $str_sql . " left join";
		$str_sql = $str_sql . " (select coalesce(b.area, 'TOTAL') as area, sum(a.qty) as qty_target, sum(a.value)/1000 as value_target";
		$str_sql = $str_sql . " from sellingout_target a";
		$str_sql = $str_sql . " inner join area b on a.area = b.area";
		$str_sql = $str_sql . " where a.tahun = '" . $year . "'";
		$str_sql = $str_sql . " group by b.area asc with rollup) b on a.area = b.area";
		$str_sql = $str_sql . " left join area c on a.area = c.area";
		$str_sql = $str_sql . " order by -c.id desc";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

	public function getChart_SI_dist($year)
	{
		$area = "JKT MT";
		$str_sql = "select x.area, x.qty as qty_actual, ifnull(sum(y.qty), 0) as qty_target, x.value as value_actual, ifnull(sum(y.value), 0) as value_target";
		$str_sql = $str_sql . " from";
		$str_sql = $str_sql . " (select COALESCE(d.area, 'TOTAL') AS area, sum(a.qty) as qty, (sum(a.value_exc) + sum(a.total_diskon))/1000 as value";
		$str_sql = $str_sql . " from selling_in a";
		$str_sql = $str_sql . " left join distributor b on a.cust_code = b.cust_code";
		$str_sql = $str_sql . " inner join area d on b.area = d.area";
		$str_sql = $str_sql . " where year(a.tanggal) = '" . $year . "'";
		$str_sql = $str_sql . " group by d.area with rollup) x";
		$str_sql = $str_sql . " left join";
		$str_sql = $str_sql . " (select distinct a.area, a.item_code, sum(a.qty) as qty, (sum(a.qty)*max(c.mt_exc))/1000 as value";
		$str_sql = $str_sql . " from sellingout_target a";
		$str_sql = $str_sql . " inner join (select distinct area from distributor) b on a.area = b.area and b.area = :area";
		$str_sql = $str_sql . " inner join pricelist c on a.item_code = c.item_code and c.valid_from <= concat(a.tahun, '-', a.bulan, '-', '01')";
		$str_sql = $str_sql . " where a.tahun = '" . $year . "'";
		$str_sql = $str_sql . " group by a.area, a.item_code";
		$str_sql = $str_sql . " union all";
		$str_sql = $str_sql . " select distinct a.area, a.item_code, sum(a.qty) as qty, (sum(a.qty)*max(c.dist_exc))/1000 as value";
		$str_sql = $str_sql . " from sellingout_target a";
		$str_sql = $str_sql . " inner join (select distinct area from distributor) b on a.area = b.area and b.area <> :area";
		$str_sql = $str_sql . " inner join pricelist c on a.item_code = c.item_code and c.valid_from <= concat(a.tahun, '-', a.bulan, '-', '01')";
		$str_sql = $str_sql . " inner join area d on a.area = d.area";
		$str_sql = $str_sql . " where a.tahun = '" . $year . "'";
		$str_sql = $str_sql . " group by a.area, a.item_code";
		$str_sql = $str_sql . " union all";
		$str_sql = $str_sql . " select 'TOTAL' as area, a.item_code, sum(a.qty) as qty, (sum(a.qty)*max(c.dist_exc))/1000 as value";
		$str_sql = $str_sql . " from sellingout_target a";
		$str_sql = $str_sql . " inner join (select distinct area from distributor) b on a.area = b.area";
		$str_sql = $str_sql . " inner join pricelist c on a.item_code = c.item_code and c.valid_from <= concat(a.tahun, '-', a.bulan, '-', '01')";
		$str_sql = $str_sql . " inner join area d on a.area = d.area";
		$str_sql = $str_sql . " where a.tahun = '" . $year . "'";
		$str_sql = $str_sql . " group by a.item_code) y on x.area = y.area";
		$str_sql = $str_sql . " left join area z on x.area = z.area";
		$str_sql = $str_sql . " group by z.area";
		$str_sql = $str_sql . " order by -z.id desc";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		$this->db->bind('area', $area);

		return $this->db->resultSet();
	}

	public function getChart_SO_asm($year)
	{
		$str_sql = "select coalesce(a.asm, 'TOTAL') as asm, sum(a.value_actual)/1000 as value_actual, sum(b.value_target)/1000 as value_target from";
		$str_sql = $str_sql . " (select b.asm, d.area, sum(a.value_exc) as value_actual";
		$str_sql = $str_sql . " from selling_out a";
		$str_sql = $str_sql . " left join distributor b on a.kode_dist = b.cust_code";
		$str_sql = $str_sql . " inner join area d on b.area = d.area";
		$str_sql = $str_sql . " where year(a.tanggal) = '" . $year . "'";
		$str_sql = $str_sql . " group by d.area";
		$str_sql = $str_sql . " order by d.id) a";
		$str_sql = $str_sql . " inner join";
		$str_sql = $str_sql . " (select b.area, sum(a.value) as value_target";
		$str_sql = $str_sql . " from sellingout_target a";
		$str_sql = $str_sql . " inner join area b on a.area = b.area";
		$str_sql = $str_sql . " where a.tahun = '" . $year . "'";
		$str_sql = $str_sql . " group by b.area";
		$str_sql = $str_sql . " order by b.id) b on a.area = b.area";
		$str_sql = $str_sql . " where a.asm <> ''";
		$str_sql = $str_sql . " group by a.asm with rollup";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

	public function getChart_SI_asm($year)
	{
		$area = "JKT MT";
		$str_sql = "select coalesce(w.asm, 'TOTAL') as asm, sum(w.qty_actual) as qty_actual, sum(w.qty_target) as qty_target, sum(w.value_actual) as value_actual, sum(w.value_target) as value_target from";
		$str_sql = $str_sql . " (select x.asm, x.qty as qty_actual, sum(y.qty) as qty_target, x.value as value_actual, sum(y.value) as value_target";
		$str_sql = $str_sql . " from (select b.asm, d.area, sum(a.qty) as qty, sum(a.value_exc)/1000 as value";
		$str_sql = $str_sql . " from selling_in a";
		$str_sql = $str_sql . " inner join distributor b on a.cust_code = b.cust_code";
		$str_sql = $str_sql . " inner join area d on b.area = d.area";
		$str_sql = $str_sql . " where year(a.tanggal) = '" . $year . "' and b.asm <> ''";
		$str_sql = $str_sql . " group by d.id, d.area, b.asm order by d.id) x";
		$str_sql = $str_sql . " inner join";
		$str_sql = $str_sql . " (select distinct a.area, a.item_code, sum(a.qty) as qty, (sum(a.qty)*max(c.mt_exc))/1000 as value";
		$str_sql = $str_sql . " from sellingout_target a";
		$str_sql = $str_sql . " inner join (select distinct area from distributor) b on a.area = b.area and b.area = :area";
		$str_sql = $str_sql . " inner join pricelist c on a.item_code = c.item_code and c.valid_from <= concat(a.tahun, '-', a.bulan, '-', '01')";
		$str_sql = $str_sql . " where a.tahun = '" . $year . "'";
		$str_sql = $str_sql . " group by a.area, a.item_code";
		$str_sql = $str_sql . " union all";
		$str_sql = $str_sql . " select distinct a.area, a.item_code, sum(a.qty) as qty, (sum(a.qty)*max(c.dist_exc))/1000 as value";
		$str_sql = $str_sql . " from sellingout_target a";
		$str_sql = $str_sql . " inner join (select distinct area from distributor) b on a.area = b.area and b.area <> :area";
		$str_sql = $str_sql . " inner join pricelist c on a.item_code = c.item_code and c.valid_from <= concat(a.tahun, '-', a.bulan, '-', '01')";
		$str_sql = $str_sql . " inner join area d on a.area = d.area";
		$str_sql = $str_sql . " where a.tahun = '" . $year . "'";
		$str_sql = $str_sql . " group by a.area, a.item_code) y on x.area = y.area";
		$str_sql = $str_sql . " inner join area z on y.area = z.area and x.area = z.area";
		$str_sql = $str_sql . " where x.asm <> ''";
		$str_sql = $str_sql . " group by z.id, x.area, x.asm order by z.id) w group by w.asm with rollup";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		$this->db->bind('area', $area);

		return $this->db->resultSet();
	}

	public function getChart_SI_dashboard($year)
	{
		$area = "JKT MT";
		$str_sql = "select x.principal, x.bulan, x.qty as qty_actual, sum(y.qty) as qty_target, x.value as value, sum(y.value) as value_target, concat(convert(round(x.value, 0), char), '/', convert(round(sum(y.value),0), char)) as v_t";
		$str_sql = $str_sql . " from (select a.principal, month(a.tanggal) as bulan, sum(a.qty) as qty, sum(a.value_exc)/1000 as value";
		$str_sql = $str_sql . " from selling_in a";
		$str_sql = $str_sql . " where year(a.tanggal) = '" . $year . "'";
		$str_sql = $str_sql . " group by a.principal, year(a.tanggal), month(a.tanggal)";
		$str_sql = $str_sql . " union all";
		$str_sql = $str_sql . " select 'TOTAL' as principal, month(a.tanggal) as bulan, sum(a.qty) as qty, sum(a.value_exc)/1000 as value";
		$str_sql = $str_sql . " from selling_in a";
		$str_sql = $str_sql . " where year(a.tanggal) = '" . $year . "'";
		$str_sql = $str_sql . " group by year(a.tanggal), month(a.tanggal)) x";
		$str_sql = $str_sql . " left join";
		$str_sql = $str_sql . " (select distinct a.principal, a.bulan, a.item_code, sum(a.qty) as qty, sum(a.value)/1000 as value";
		$str_sql = $str_sql . " from sellingin_target a";
		$str_sql = $str_sql . " inner join (select distinct area from distributor) b on a.area = b.area and b.area = :area";
		$str_sql = $str_sql . " where a.tahun = '" . $year . "'";
		$str_sql = $str_sql . " group by a.principal, a.bulan, a.item_code";
		$str_sql = $str_sql . " union all";
		$str_sql = $str_sql . " select distinct a.principal, a.bulan, a.item_code, sum(a.qty) as qty, sum(a.value)/1000 as value";
		$str_sql = $str_sql . " from sellingin_target a";
		$str_sql = $str_sql . " inner join (select distinct area from distributor) b on a.area = b.area and b.area <> :area";
		$str_sql = $str_sql . " inner join area d on a.area = d.area";
		$str_sql = $str_sql . " where a.tahun = '" . $year . "'";
		$str_sql = $str_sql . " group by a.principal, a.bulan, a.item_code";
		$str_sql = $str_sql . " union all";
		$str_sql = $str_sql . " select distinct 'TOTAL' as principal, a.bulan, a.item_code, sum(a.qty) as qty, sum(a.value)/1000 as value";
		$str_sql = $str_sql . " from sellingin_target a";
		$str_sql = $str_sql . " inner join (select distinct area from distributor) b on a.area = b.area and b.area = :area";
		$str_sql = $str_sql . " where a.tahun = '" . $year . "'";
		$str_sql = $str_sql . " group by a.bulan, a.item_code";
		$str_sql = $str_sql . " union all";
		$str_sql = $str_sql . " select distinct 'TOTAL' as principal, a.bulan, a.item_code, sum(a.qty) as qty, sum(a.value)/1000 as value";
		$str_sql = $str_sql . " from sellingin_target a";
		$str_sql = $str_sql . " inner join (select distinct area from distributor) b on a.area = b.area and b.area <> :area";
		$str_sql = $str_sql . " inner join area d on a.area = d.area";
		$str_sql = $str_sql . " where a.tahun = '" . $year . "'";
		$str_sql = $str_sql . " group by a.bulan, a.item_code) y on x.principal = y.principal and x.bulan = y.bulan";
		$str_sql = $str_sql . " group by x.principal, x.bulan, x.qty, x.value;";

		// Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		$this->db->bind('area', $area);

		return $this->db->resultSet();
	}

	public function getChart_SO_dashboard($year)
	{
		$str_sql = "select x.principal, x.bulan, x.qty as qty, sum(y.qty_target) as qty_target, x.value as value, sum(y.value_target) as value_target,";
		$str_sql = $str_sql . " concat(convert(round(x.value, 0), char), '/', convert(round(sum(y.value_target),0), char)) as v_t";
		$str_sql = $str_sql . " from";
		$str_sql = $str_sql . " (select a.principal, month(a.tanggal) as bulan, sum(a.qty) as qty, sum(a.value_exc)/1000 as value";
		$str_sql = $str_sql . " from selling_out a";
		$str_sql = $str_sql . " where year(a.tanggal) = '" . $year . "' and a.principal <> 'OTHERS'";
		$str_sql = $str_sql . " group by a.principal, year(a.tanggal), month(a.tanggal)";
		$str_sql = $str_sql . " union all";
		$str_sql = $str_sql . " select 'TOTAL' as principal, month(a.tanggal) as bulan, sum(a.qty) as qty, sum(a.value_exc)/1000 as value";
		$str_sql = $str_sql . " from selling_out a";
		$str_sql = $str_sql . " where year(a.tanggal) = '" . $year . "' and a.principal <> 'OTHERS'";
		$str_sql = $str_sql . " group by year(a.tanggal), month(a.tanggal)) x";
		$str_sql = $str_sql . " left join";
		$str_sql = $str_sql . " (select principal, tahun, bulan, sum(qty) as qty_target, sum(value)/1000 as value_target";
		$str_sql = $str_sql . " from sellingout_target";
		$str_sql = $str_sql . " where tahun = '" . $year . "'";
		$str_sql = $str_sql . " group by principal, tahun, bulan";
		$str_sql = $str_sql . " union all";
		$str_sql = $str_sql . " select 'TOTAL' as principal, tahun, bulan, sum(qty) as qty_target, sum(value)/1000 as value_target";
		$str_sql = $str_sql . " from sellingout_target";
		$str_sql = $str_sql . " where tahun = '" . $year . "'";
		$str_sql = $str_sql . " group by tahun, bulan) y";
		$str_sql = $str_sql . " on x.principal = y.principal and x.bulan = y.bulan";
		$str_sql = $str_sql . " group by x.principal, x.bulan, y.value_target";

		// Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

	public function getChart_SO_dashboard2($year)
	{
		$str_sql = "select a.principal, month(a.tanggal) as bulan, sum(a.qty) as qty, b.qty_target, sum(a.value_exc)/1000 as value, b.value_target";
		$str_sql = $str_sql . " from selling_out a";
		$str_sql = $str_sql . " left join";
		$str_sql = $str_sql . " (select principal, tahun, bulan, sum(qty) as qty_target, sum(value)/1000 as value_target  from sellingout_target group by principal, tahun, bulan) b";
		$str_sql = $str_sql . " on a.principal = b.principal and year(a.tanggal) = b.tahun and month(a.tanggal) = b.bulan";
		$str_sql = $str_sql . " where year(a.tanggal) = '" . $year . "'";
		$str_sql = $str_sql . " group by a.principal, year(a.tanggal), month(a.tanggal), b.value_target";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

	public function getChartOutMonthTOTAL()
	{
		foreach ($this->getMaxYear() as $row) :
