	public function getChartOutWeekTOTAL()
	{

		foreach ($this->getMaxMonth() as $row) :
			$max_month = $row['max_month'];
		endforeach;

		if (isset($_POST['bulan']))
		{
			$bulan = $_POST['bulan'];
		}else
		{
			$bulan = $max_month;
		}

		$str_sql = "select 'TOTAL' as channel, month(a.tanggal) as no_month,";
		$str_sql = $str_sql . " week(a.tanggal,7) - WEEK(DATE_SUB(a.tanggal, INTERVAL DAYOFMONTH(a.tanggal)-1 DAY),5)+1 as no_week,";
		$str_sql = $str_sql . " sum(a.qty) as qty";
		$str_sql = $str_sql . " from selling_out a";
		$str_sql = $str_sql . " where a.item_name <> 42 and month(a.tanggal) = " . $bulan . "";
		$str_sql = $str_sql . " group by no_month, no_week";
		$str_sql = $str_sql . " order by no_month, no_week";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

	public function getSellingIn()
	{
