		}else
		{
			$month1 = '1';
		}
		if(isset($_POST['by_month2']))
		{
			$month2 = $_POST['by_month2'];
		}else
		{
			$month2 = $month_so;
		}

		if(isset($_POST['by_year']))
		{
			$year = $_POST['by_year'];
		}else
		{
			$year = $year_so;
		}

		$area = "JKT MT";

		$str_sql = "SELECT a.id, a.channel, a.outlet_category, a.desc_type, a.outlet_type,";
		$str_sql = $str_sql . " sum(if(isnull(c.qty), b.qty, c.qty)) as qty,";
		$str_sql = $str_sql . " sum(if(isnull(c.value), b.value, c.value)) as val";
		$str_sql = $str_sql . " FROM channel a";
		$str_sql = $str_sql . " LEFT JOIN";
		$str_sql = $str_sql . " (select cc.outlet_type, sum(aa.qty) as qty, (sum(aa.value_exc)+sum(aa.total_diskon))/1000 as value";
		$str_sql = $str_sql . " from selling_in aa";
		$str_sql = $str_sql . " right join sku bb on aa.item_code = bb.item_code";
		$str_sql = $str_sql . " left join outlet cc on aa.cust_code = cc.outlet_code";
		$str_sql = $str_sql . " left join area dd on cc.area = dd.area";
		$str_sql = $str_sql . " where dd.area = :area and (month(aa.tanggal) between :month1 and :month2) and year(aa.tanggal) = :year";

		if (isset($principal))
		{
			if($principal != '')
			{
				$str_sql = $str_sql . " and aa.principal = :principal";
