		if (isset($island))
		{
			if($island != '')
			{
				$str_sql = $str_sql . " and dd.island = :island";
			}
		}
		
		if (isset($groupsku))
		{
			if($groupsku != '')
			{
				$str_sql = $str_sql . " and bb.item_group = :groupsku";
			}
		}

		$str_sql = $str_sql . " group by cc.outlet_type) b on a.outlet_type = b.outlet_type";

		$str_sql = $str_sql . " LEFT JOIN";
		$str_sql = $str_sql . " (select 'DIST' as outlet_type, sum(aa.qty) as qty, (sum(aa.value_exc)+sum(aa.total_diskon))/1000 as value";
		$str_sql = $str_sql . " from selling_in aa";
		$str_sql = $str_sql . " right join sku bb on aa.item_code = bb.item_code";
		$str_sql = $str_sql . " left join distributor cc on aa.cust_code = cc.cust_code";
		$str_sql = $str_sql . " left join area dd on cc.area = dd.area";
		$str_sql = $str_sql . " where (month(aa.tanggal) between :month1 and :month2) and year(aa.tanggal) = :year";

		if (isset($principal))
		{
			if($principal != '')
			{
				$str_sql = $str_sql . " and aa.principal = :principal";
			}
		}
		if (isset($sku))
		{
			if($sku != '')
			{
				$str_sql = $str_sql . " and aa.item_name = :sku";
			}
		}

		if (isset($island))
		{
			if($island != '')
			{
				$str_sql = $str_sql . " and dd.island = :island";
			}
		}
		
		if (isset($groupsku))
		{
			if($groupsku != '')
			{
				$str_sql = $str_sql . " and bb.item_group = :groupsku";
			}
		}

		$str_sql = $str_sql . " group by outlet_type) c on a.outlet_type = c.outlet_type";
		
		$str_sql = $str_sql . " GROUP BY a.channel, a.outlet_type";
		$str_sql = $str_sql . " ORDER BY a.id asc;";

		// Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		$this->db->bind('area', $area);
		$this->db->bind('month1', $month1);
		$this->db->bind('month2', $month2);
		$this->db->bind('year', $year);
		
		if (isset($principal) and $principal != '')
		{
			$this->db->bind('principal', $principal);
		}
		if (isset($sku) and $sku != '')
		{
			$this->db->bind('sku', $sku);
		}
		if (isset($island) and $island != '')
		{
			$this->db->bind('island', $island);
		}
		if (isset($groupsku) and $groupsku != '')
		{
			$this->db->bind('groupsku', $groupsku);
		}

		return $this->db->resultSet();
	}

