		}else
		{
			$month1 = '1';
		}
		if(isset($_POST['by_month2']))
		{
			$month2 = $_POST['by_month2'];
		}else
		{
			$month2 = date('m');
		}

		if(isset($_POST['by_year']))
		{
			$year = $_POST['by_year'];
		}else
		{
			$year = date('Y');
		}

		$str_sql = "SELECT a.id, a.channel, a.outlet_category, a.desc_type, a.outlet_type, sum(b.qty) as qty, sum(b.value_exc)/1000 as val";
		$str_sql = $str_sql . " FROM channel a";
		$str_sql = $str_sql . " left join ";
		$str_sql = $str_sql . " (select aa.tanggal, aa.invoice, aa.outlet_type, aa.item_code, sum(aa.qty) as qty, sum(aa.value_exc) as value_exc";
		$str_sql = $str_sql . " from selling_out aa";
		$str_sql = $str_sql . " inner join sku cc on aa.item_code = cc.item_code";
		$str_sql = $str_sql . " inner join area dd on aa.area = dd.area";
		$str_sql = $str_sql . " where (month(aa.tanggal) between '" . $month1 . "' and '" . $month2 . "') and year(aa.tanggal) = '" . $year . "'";
		$str_sql = $str_sql . " and aa.outlet_type <> 'DIST'";

		if (isset($principal))
		{
			if($principal != '')
			{
				$str_sql = $str_sql . " and aa.principal = '" . $principal . "'";
			}
		}
		if (isset($sku))
		{
			if($sku != '')
			{
				$str_sql = $str_sql . " and cc.item_name = '" . $sku . "'";
			}
		}

		if (isset($island))
		{
			if($island != '')
			{
				$str_sql = $str_sql . " and dd.island = '" . $island . "'";
			}
		}

		if (isset($groupsku))
		{
			if($groupsku != '')
			{
				$str_sql = $str_sql . " and cc.item_group = '" . $groupsku . "'";
			}
		}

		if ($_SESSION['area'] != 'ALL')
		{
			$session_area = str_replace(",", "','", $_SESSION['area']);
			$session_area = str_replace(" ", "", $session_area);

			$str_sql = $str_sql . " and dd.area in ('" . $session_area . "')";
		}

		$str_sql = $str_sql . " group by aa.tanggal, aa.invoice, aa.item_code";
		$str_sql = $str_sql . " order by aa.tanggal) b on a.outlet_type = b.outlet_type";
		$str_sql = $str_sql . " GROUP BY a.channel, a.outlet_type";
		$str_sql = $str_sql . " ORDER BY a.id asc";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

