	public function getSellingIn_Dist_SUM($dataDist)
	{
		$area = str_replace(",", "','", $_SESSION['area']);
		$area = str_replace(" ", "", $area);

		$data1 = explode(",", $dataDist);
		$principal = $data1[0];
		$year = $data1[1];

		$str_sql = "SELECT distinct b.cust_code, b.distributor, b.area, b.region, b.island,";
		$str_sql = $str_sql . " d.qty as qty_jan, d.value as val_jan, e.qty as qty_feb, e.value as val_feb,"; 
		$str_sql = $str_sql . " f.qty as qty_mar, f.value as val_mar, g.qty as qty_apr, g.value as val_apr,"; 
		$str_sql = $str_sql . " h.qty as qty_mei, h.value as val_mei, i.qty as qty_jun, i.value as val_jun,"; 
		$str_sql = $str_sql . " j.qty as qty_jul, j.value as val_jul, k.qty as qty_agu, k.value as val_agu,"; 
		$str_sql = $str_sql . " l.qty as qty_sep, l.value as val_sep, m.qty as qty_okt, m.value as val_okt,"; 
		$str_sql = $str_sql . " n.qty as qty_nop, n.value as val_nop, o.qty as qty_des, o.value as val_des,"; 
		$str_sql = $str_sql . " (coalesce(d.qty,0) + coalesce(e.qty,0) + coalesce(f.qty,0) + coalesce(g.qty,0) +";
		$str_sql = $str_sql . " coalesce(h.qty,0) + coalesce(i.qty,0) + coalesce(j.qty,0) + coalesce(k.qty,0) +";
		$str_sql = $str_sql . " coalesce(l.qty,0) + coalesce(m.qty,0) + coalesce(n.qty,0) + coalesce(o.qty,0)) as qty_year,";
		$str_sql = $str_sql . " (coalesce(d.value,0) + coalesce(e.value,0) + coalesce(f.value,0) + coalesce(g.value,0) +";
		$str_sql = $str_sql . " coalesce(h.value,0) + coalesce(i.value,0) + coalesce(j.value,0) + coalesce(k.value,0) +";
		$str_sql = $str_sql . " coalesce(l.value,0) + coalesce(m.value,0) + coalesce(n.value,0) + coalesce(o.value,0)) as val_year";
		$str_sql = $str_sql . " FROM " . $this->table_sellingin . " a";
		$str_sql = $str_sql . " right join (select y.id, x.cust_code, x.distributor, y.area, y.region, y.island, x.pic from distributor x inner join area y on x.area = y.area order by y.id) b on a.cust_code = b.cust_code";
		if (isset($principal))
		{
			if($principal != '')
