	public function getSellingIn_OT($ot)
	{
		$data1 = explode(",", $ot);
		$year = $data1[1];
		$id = $data1[0];

		$str_sql = "SELECT distinct b.outlet_code, b.outlet_name, b.area, c.channel, c.outlet_type,";
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '1', a.qty, 0)) as qty_jan,"; 
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '1', (a.value_exc + a.total_diskon)/1000, 0)) as val_jan,";
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '2', a.qty, 0)) as qty_feb,"; 
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '2', (a.value_exc + a.total_diskon)/1000, 0)) as val_feb,";
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '3', a.qty, 0)) as qty_mar,"; 
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '3', (a.value_exc + a.total_diskon)/1000, 0)) as val_mar,";
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '4', a.qty, 0)) as qty_apr,"; 
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '4', (a.value_exc + a.total_diskon)/1000, 0)) as val_apr,";
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '5', a.qty, 0)) as qty_mei,"; 
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '5', (a.value_exc + a.total_diskon)/1000, 0)) as val_mei,";
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '6', a.qty, 0)) as qty_jun,"; 
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '6', (a.value_exc + a.total_diskon)/1000, 0)) as val_jun,";
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '7', a.qty, 0)) as qty_jul,"; 
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '7', (a.value_exc + a.total_diskon)/1000, 0)) as val_jul,";
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '8', a.qty, 0)) as qty_agu,"; 
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '8', (a.value_exc + a.total_diskon)/1000, 0)) as val_agu,";
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '9', a.qty, 0)) as qty_sep,"; 
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '9', (a.value_exc + a.total_diskon)/1000, 0)) as val_sep,";
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '10', a.qty, 0)) as qty_okt,"; 
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '10', (a.value_exc + a.total_diskon)/1000, 0)) as val_okt,";
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '11', a.qty, 0)) as qty_nop,"; 
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '11', (a.value_exc + a.total_diskon)/1000, 0)) as val_nop,";
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '12', a.qty, 0)) as qty_des,"; 
		$str_sql = $str_sql . " sum( if( month(a.tanggal) = '12', (a.value_exc + a.total_diskon)/1000, 0)) as val_des,";
		$str_sql = $str_sql . " sum(a.qty) as qty_year, (sum(value_exc)+sum(total_diskon))/1000 as val_year";		 
		$str_sql = $str_sql . " FROM " . $this->table_sellingin . " a";
		$str_sql = $str_sql . " right join outlet b on a.cust_code = b.outlet_code";
		$str_sql = $str_sql . " inner join channel c on b.outlet_type = c.outlet_type";
		$str_sql = $str_sql . " where c.id = '".$id."' and b.area = 'JKT MT' and year(a.tanggal) = '" . $year . "'";

		$str_sql = $str_sql . " GROUP BY b.outlet_code ORDER BY b.outlet_code";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

