			$str_sql = $str_sql . " left join (select distinct a.cust_code, a.cust_name, '0' as qty";
			$str_sql = $str_sql . " from selling_in a";
			$str_sql = $str_sql . " left join dc b on a.cust_code = b.outlet_code";
			$str_sql = $str_sql . " where tanggal between DATE_SUB(concat('" . $year . "', '-12-1'), INTERVAL 12 month) and LAST_DAY(concat('" . $year . "', '-12-1')) and a.qty >= 0";
			$str_sql = $str_sql . " group by cust_code) o on b.outlet_code = o.cust_code";
		}

		$str_sql = $str_sql . " where b.area = 'JKT MT'";

		if (isset($principal))
		{
			if($principal != '')
			{
				$str_sql = $str_sql . " and a.principal = '" . $principal . "'";
			}
		}

		if (isset($outlet_type))
		{
			if($outlet_type != '')
			{
				$str_sql = $str_sql . " and c.outlet_type = '" . $outlet_type . "'";
			}
		}

		$str_sql = $str_sql . " GROUP BY b.outlet_code ORDER BY b.outlet_code";

		////Flasher::setMessage('Berhasil', $str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

	public function getDistribution_OT()
	{

		if (isset($_POST['by_principal']))
