			$str_sql = $str_sql . " max( if( tanggal between DATE_SUB(concat('" . $year . "', '-01-1'), INTERVAL 11 month) and LAST_DAY(concat('" . $year . "', '-01-1')), b.total_outlet, 0)) as qty_jan,"; 
			$str_sql = $str_sql . " max( if( tanggal between DATE_SUB(concat('" . $year . "', '-02-1'), INTERVAL 11 month) and LAST_DAY(concat('" . $year . "', '-02-1')), b.total_outlet, 0)) as qty_feb,"; 
			$str_sql = $str_sql . " max( if( tanggal between DATE_SUB(concat('" . $year . "', '-03-1'), INTERVAL 11 month) and LAST_DAY(concat('" . $year . "', '-03-1')), b.total_outlet, 0)) as qty_mar,"; 
			$str_sql = $str_sql . " max( if( tanggal between DATE_SUB(concat('" . $year . "', '-04-1'), INTERVAL 11 month) and LAST_DAY(concat('" . $year . "', '-04-1')), b.total_outlet, 0)) as qty_apr,"; 
			$str_sql = $str_sql . " max( if( tanggal between DATE_SUB(concat('" . $year . "', '-05-1'), INTERVAL 11 month) and LAST_DAY(concat('" . $year . "', '-05-1')), b.total_outlet, 0)) as qty_mei,"; 
			$str_sql = $str_sql . " max( if( tanggal between DATE_SUB(concat('" . $year . "', '-06-1'), INTERVAL 11 month) and LAST_DAY(concat('" . $year . "', '-06-1')), b.total_outlet, 0)) as qty_jun,"; 
			$str_sql = $str_sql . " max( if( tanggal between DATE_SUB(concat('" . $year . "', '-07-1'), INTERVAL 11 month) and LAST_DAY(concat('" . $year . "', '-07-1')), b.total_outlet, 0)) as qty_jul,"; 
			$str_sql = $str_sql . " max( if( tanggal between DATE_SUB(concat('" . $year . "', '-08-1'), INTERVAL 11 month) and LAST_DAY(concat('" . $year . "', '-08-1')), b.total_outlet, 0)) as qty_agu,"; 
			$str_sql = $str_sql . " max( if( tanggal between DATE_SUB(concat('" . $year . "', '-09-1'), INTERVAL 11 month) and LAST_DAY(concat('" . $year . "', '-09-1')), b.total_outlet, 0)) as qty_sep,"; 
			$str_sql = $str_sql . " max( if( tanggal between DATE_SUB(concat('" . $year . "', '-10-1'), INTERVAL 11 month) and LAST_DAY(concat('" . $year . "', '-10-1')), b.total_outlet, 0)) as qty_okt,"; 
			$str_sql = $str_sql . " max( if( tanggal between DATE_SUB(concat('" . $year . "', '-11-1'), INTERVAL 11 month) and LAST_DAY(concat('" . $year . "', '-11-1')), b.total_outlet, 0)) as qty_nop,"; 
			$str_sql = $str_sql . " max( if( tanggal between DATE_SUB(concat('" . $year . "', '-12-1'), INTERVAL 11 month) and LAST_DAY(concat('" . $year . "', '-12-1')), b.total_outlet, 0)) as qty_des";

		}
		elseif ($year >= $year_so)
		{
			$str_sql = $str_sql . " 0 as qty_jan, 0 as qty_feb, 0 as qty_mar, 0 as qty_apr, 0 as qty_mei, 0 as qty_jun,";
			$str_sql = $str_sql . " 0 as qty_jul, 0 as qty_agu, 0 as qty_sep, 0 as qty_okt, 0 as qty_nop, 0 as qty_des";
		}

		$str_sql = $str_sql . " FROM " . $this->table_sellingout . " a";
		$str_sql = $str_sql . " INNER JOIN outlet b on a.big_code = b.big_code and a.outlet_type = b.outlet_type and a.area = b.area";
		$str_sql = $str_sql . " INNER JOIN channel c on a.outlet_type = c.outlet_type";
		$str_sql = $str_sql . " INNER JOIN distributor d on b.dist_code = d.cust_code and b.area = d.area";
		$str_sql = $str_sql . " WHERE a.inv_status in ('INVOICE', 'RETURN')";
		// $str_sql = $str_sql . " and year(a.tanggal) in ('" . $interval_year . "', '" . $year . "')";
		// $str_sql = $str_sql . " and a.tanggal >= '".$interval_year."-02-1' ";

		//$str_sql = $str_sql . " where b.area = 'JKT MT'";

		if (isset($principal))
		{
			if($principal != '')
			{
				$str_sql = $str_sql . " and a.principal = '" . $principal . "'";
			}
		}
		if (isset($channel))
		{
			if($channel != '')
			{
				$str_sql = $str_sql . " and c.channel = '" . $channel . "'";
			}
		}
		if (isset($outlet_type))
		{
			if($outlet_type != '')
			{
				$str_sql = $str_sql . " and c.outlet_type = '" . $outlet_type . "'";
			}
		}
		if (isset($area))
		{
			if($area != '')
			{
				$str_sql = $str_sql . " and a.area in ('" . $area . "')";
			}
			else
			{
				if ($_SESSION['area'] != 'ALL')
				{
					$session_area = str_replace(",", "','", $_SESSION['area']);
					$session_area = str_replace(" ", "", $session_area);

					$str_sql = $str_sql . " and a.area in ('" . $session_area . "')";
				}
			}
		}
		else
		{
			if ($_SESSION['area'] != 'ALL')
			{
				$session_area = str_replace(",", "','", $_SESSION['area']);
				$session_area = str_replace(" ", "", $session_area);

				$str_sql = $str_sql . " and a.area in ('" . $session_area . "')";
			}
		}
		

		$str_sql = $str_sql . " GROUP BY a.big_code ORDER BY a.big_code";

		// Flasher::setMessage('Berhasil', $str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

	public function getRO_outlet()
	{

		if (isset($_POST['by_principal']))
		{
			$principal = $_POST['by_principal'];
		}
		if (isset($_POST['by_channel']))
		{
			$channel = $_POST['by_channel'];
		}
		if (isset($_POST['by_outlet_type']))
		{
			$outlet_type = $_POST['by_outlet_type'];
		}
		if (isset($_POST['by_year']))
		{
			$year = $_POST['by_year'];
		}else
		{
			$year = date('Y');
		}
		if (isset($_POST['by_month']))
		{
			$month = $_POST['by_month'];
		}else
		{
			$month = date('m');
		}
		if (isset($_POST['by_area']))
		{
			array_push($area_arr, str_replace("__", " ", $data[$a]));
			$area = implode(',', $_POST['by_area']);
			$area = str_replace(",", "','", $area);
		}
		elseif ($_SESSION['area'] != 'ALL')
		{
			$session_area = str_replace(", ", "','", $_SESSION['area']); 
			$area = $session_area;
		}

		$fromdate = '-' .$month. '-1';

		$str_sql = "SELECT DISTINCT a.id as id, b.big_code, b.outlet_code, b.outlet_name, b.area, a.channel, a.desc_type, a.outlet_type, b.ro, b.dist_code, b.distributor,";
		$str_sql = $str_sql . " SUM( IF( ISNULL(c.DISTR), 0, c.DISTR)) as distr, SUM( IF( ISNULL(d.AO), 0, d.AO)) as ao";
		$str_sql = $str_sql . " FROM channel a";
		$str_sql = $str_sql . " INNER JOIN (";
					$str_sql = $str_sql . " select a.id, a.big_code, a.outlet_code, a.outlet_name, a.area, c.outlet_type, a2.dist_code, b.distributor, a2.total_outlet as ro";
					$str_sql = $str_sql . " from outlet a";
					$str_sql = $str_sql . " inner join (select big_code, outlet_code, area, max(dist_code) as dist_code, max(total_outlet) total_outlet, max(register_date) as register_date";
								$str_sql = $str_sql . " from outlet";
								$str_sql = $str_sql . " group by big_code, area";
								$str_sql = $str_sql . " ) a2 on a.big_code = a2.big_code and a.area = a2.area and a.register_date = a2.register_date";
					$str_sql = $str_sql . " inner join distributor b on a2.dist_code = b.cust_code and a.area = b.area";
					$str_sql = $str_sql . " inner join channel c on a.outlet_type = c.outlet_type";
					$str_sql = $str_sql . " inner join area d on a.area = d.area";
					$str_sql = $str_sql . " where a.register_date <= last_day(concat('" . $year . "', '".$fromdate."'))";
					if (isset($channel))
					{
						if($channel != '')
						{
							$str_sql = $str_sql . " and c.channel = '" . $channel . "'";
						}
					}
					if (isset($outlet_type))
					{
						if($outlet_type != '')
						{
							$str_sql = $str_sql . " and a.outlet_type = '" . $outlet_type . "'";
						}
					}
					if (isset($area))
					{
						if($area != '')
						{
							$str_sql = $str_sql . " and a.area in ('" . $area . "')";
						}
					}
					$str_sql = $str_sql . " group by a.outlet_type, a.big_code, a.area";
					$str_sql = $str_sql . " order by a.big_code";
					$str_sql = $str_sql . " ) b on a.outlet_type = b.outlet_type";
		$str_sql = $str_sql . " LEFT JOIN (";
					$str_sql = $str_sql . " select x.big_code, x.cust_code, x.cust_name, x.area, x.outlet_type, x.kode_dist, x.nama_dist, max(z.total_outlet) as DISTR";
					$str_sql = $str_sql . " from selling_out x";
					$str_sql = $str_sql . " left join area y on x.area = y.area";
					$str_sql = $str_sql . " inner join outlet z on x.big_code = z.big_code and x.outlet_type = z.outlet_type and x.area = z.area";
					$str_sql = $str_sql . " inner join channel zz on z.outlet_type = zz.outlet_type";
					$str_sql = $str_sql . " where x.tanggal between DATE_SUB(concat('" . $year . "', '".$fromdate."'), INTERVAL 11 month) and LAST_DAY(concat('" . $year . "', '".$fromdate."'))";
					if (isset($principal))
					{
						if($principal != '')
						{
							$str_sql = $str_sql . " and x.principal = '" . $principal . "'";
						}
					}
					if (isset($channel))
					{
						if($channel != '')
						{
							$str_sql = $str_sql . " and zz.channel = '" . $channel . "'";
						}
					}
					if (isset($outlet_type))
					{
						if($outlet_type != '')
						{
							$str_sql = $str_sql . " and x.outlet_type = '" . $outlet_type . "'";
						}
					}
					if (isset($area))
					{
						if($area != '')
						{
							$str_sql = $str_sql . " and x.area in ('" . $area . "')";
						}
					}
					$str_sql = $str_sql . " group by x.outlet_type, x.big_code, x.area";
					$str_sql = $str_sql . " ) c on a.outlet_type = c.outlet_type AND b.big_code = c.big_code AND b.area = c.area";
		$str_sql = $str_sql . " LEFT JOIN (";
					$str_sql = $str_sql . " select x.big_code, x.cust_code, x.cust_name, x.area, x.outlet_type, x.kode_dist, x.nama_dist, max(z.total_outlet) as AO";
					$str_sql = $str_sql . " from selling_out x";
					$str_sql = $str_sql . " left join area y on x.area = y.area";
					$str_sql = $str_sql . " inner join outlet z on x.big_code = z.big_code and x.outlet_type = z.outlet_type and x.area = z.area and z.total_outlet >= 1";
					$str_sql = $str_sql . " inner join channel zz on z.outlet_type = zz.outlet_type";
					$str_sql = $str_sql . " where month(x.tanggal) = '".$month."' and year(x.tanggal) = '".$year."'";
					if (isset($principal))
					{
						if($principal != '')
						{
							$str_sql = $str_sql . " and x.principal = '" . $principal . "'";
						}
					}
					if (isset($channel))
					{
						if($channel != '')
						{
							$str_sql = $str_sql . " and zz.channel = '" . $channel . "'";
						}
					}
					if (isset($outlet_type))
					{
						if($outlet_type != '')
						{
							$str_sql = $str_sql . " and x.outlet_type = '" . $outlet_type . "'";
						}
					}
					if (isset($area))
					{
						if($area != '')
						{
							$str_sql = $str_sql . " and x.area in ('" . $area . "')";
						}
					}
					$str_sql = $str_sql . " group by x.outlet_type, x.big_code, x.area";
					$str_sql = $str_sql . " ) d on a.outlet_type = d.outlet_type AND b.big_code = d.big_code AND b.area = d.area";
		
		$str_sql = $str_sql . " GROUP BY a.outlet_type, b.big_code";
		$str_sql = $str_sql . " ORDER BY a.id, b.big_code, b.outlet_code";

		// Flasher::setMessage('Berhasil', $str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

	public function getRO_outlet2($direct)
	{

		$data = explode(",", $direct);

		$principal = $data[0];
		$outlet_type = str_replace("__", " ", $data[1]);
		$year = $data[2];
		$month = $data[3];
		$count = count($data);

		if ($count > 5)
		{
			//$area = str_replace("__", " ", $data[3]);
			$area_arr = array();
			for ($a = 4; $a <= $count-1; $a ++) {
				array_push($area_arr, str_replace("__", " ", $data[$a]));
			}
			$area = implode(',', $area_arr);
			$area = str_replace(",", "','", $area);
		}
		elseif ($count = 5)
		{
			$area = str_replace("__", " ", $data[4]);
		}
		
		$fromdate = '-' .$month. '-1';
		// $get['period_si'] = $this->getMonth_SO();
		// $month = $get['period_si']['to_month'];
		// $year_so = $get['period_si']['year'];

		//$maxyear_so = $this->getMaxYear_SO();

		$str_sql = "SELECT a.id, a.big_code, a.outlet_code, a.outlet_name, a.area, a.outlet_type, max(a.total_outlet) as ro,";
		$str_sql = $str_sql . " if(isnull(e.kode_dist), a.dist_code, max(e.kode_dist)) as dist_code,";
		$str_sql = $str_sql . " if(isnull(e.nama_dist), b.distributor, max(e.nama_dist)) as distributor,";
		$str_sql = $str_sql . " if(isnull(e.big_code), '0', max(a.total_outlet)) as distr";
		$str_sql = $str_sql . " FROM outlet a";
		$str_sql = $str_sql . " LEFT JOIN distributor b on a.dist_code = b.cust_code and a.area = b.area ";
		$str_sql = $str_sql . " INNER JOIN channel c on a.outlet_type = c.outlet_type";
		$str_sql = $str_sql . " INNER JOIN area d on a.area = d.area";
		$str_sql = $str_sql . " LEFT JOIN selling_out e on a.big_code = e.big_code and a.area = e.area and a.outlet_type = e.outlet_type and e.tanggal between DATE_SUB(concat('" . $year . "', '".$fromdate."'), INTERVAL 11 month) and LAST_DAY(concat('" . $year . "', '".$fromdate."'))";
		if (isset($principal))
		{
			if($principal != '')
			{
				$str_sql = $str_sql . " and e.principal = '" . $principal . "'";
			}
		}
		// $str_sql = $str_sql . " WHERE b.is_active in (1, 0)";
		$str_sql = $str_sql . " WHERE a.register_date <= last_day(concat('" . $year . "', '".$fromdate."')) ";

		//$str_sql = $str_sql . " where b.area = 'JKT MT'";

		
		if (isset($channel))
		{
			if($channel != '')
			{
				$str_sql = $str_sql . " AND c.channel = '" . $channel . "'";
			}
		}
		if (isset($outlet_type))
		{
			if($outlet_type != '')
			{
				$str_sql = $str_sql . " AND a.outlet_type = '" . $outlet_type . "'";
			}
		}
		if (isset($area))
		{
			if($area != '')
			{
				$str_sql = $str_sql . " AND a.area in ('" . $area . "')";
			}
			else
			{
				if ($_SESSION['area'] != 'ALL')
				{
					$session_area = str_replace(",", "','", $_SESSION['area']);
					$session_area = str_replace(" ", "", $session_area);

					$str_sql = $str_sql . " AND a.area in ('" . $session_area . "')";
				}
			}
		}
		else
		{
			if ($_SESSION['area'] != 'ALL')
			{
				$session_area = str_replace(",", "','", $_SESSION['area']);
				$session_area = str_replace(" ", "", $session_area);

				$str_sql = $str_sql . " AND a.area in ('" . $session_area . "')";
			}
		}
		

		//$str_sql = $str_sql . " GROUP BY a.outlet_code, a.area";
		$str_sql = $str_sql . " GROUP BY a.big_code";
		$str_sql = $str_sql . " ORDER BY a.id";

		// Flasher::setMessage('Berhasil', $str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

	public function getRO_outlet3($direct)
	{

		$data = explode(",", $direct);

		$principal = $data[0];
		$outlet_type = str_replace("__", " ", $data[1]);
		$year = $data[2];
		$month = $data[3];
		$count = count($data);

		if ($count > 5)
		{
			//$area = str_replace("__", " ", $data[3]);
			$area_arr = array();
			for ($a = 4; $a <= $count-1; $a ++) {
				array_push($area_arr, str_replace("__", " ", $data[$a]));
			}
			$area = implode(',', $area_arr);
			$area = str_replace(",", "','", $area);
		}
		elseif ($count = 5)
		{
			$area = str_replace("__", " ", $data[4]);
		}
		
		$fromdate = '-' .$month. '-1';
		// $get['period_si'] = $this->getMonth_SO();
		// $month = $get['period_si']['to_month'];
		// $year_so = $get['period_si']['year'];

		//$maxyear_so = $this->getMaxYear_SO();

		$str_sql = "SELECT DISTINCT a.id as id, b.big_code, b.outlet_code, b.outlet_name, b.area, a.channel, a.desc_type, a.outlet_type, b.ro, b.dist_code, b.distributor,";
		$str_sql = $str_sql . " SUM( IF( ISNULL(c.DISTR), 0, c.DISTR)) as distr, SUM( IF( ISNULL(d.AO), 0, d.AO)) as ao";
		$str_sql = $str_sql . " FROM channel a";
		$str_sql = $str_sql . " INNER JOIN (";
					$str_sql = $str_sql . " select a.id, a.big_code, a.outlet_code, a.outlet_name, a.area, c.outlet_type, a2.dist_code, b.distributor, a2.total_outlet as ro";
					$str_sql = $str_sql . " from outlet a";
					$str_sql = $str_sql . " inner join (select big_code, outlet_code, area, max(dist_code) as dist_code, max(total_outlet) total_outlet, max(register_date) as register_date";
								$str_sql = $str_sql . " from outlet";
								$str_sql = $str_sql . " group by big_code, area";
								$str_sql = $str_sql . " ) a2 on a.big_code = a2.big_code and a.area = a2.area and a.register_date = a2.register_date";
					$str_sql = $str_sql . " inner join distributor b on a2.dist_code = b.cust_code and a.area = b.area";
					$str_sql = $str_sql . " inner join channel c on a.outlet_type = c.outlet_type";
					$str_sql = $str_sql . " inner join area d on a.area = d.area";
					$str_sql = $str_sql . " where a.register_date <= last_day(concat('" . $year . "', '".$fromdate."'))";
					if (isset($channel))
					{
						if($channel != '')
						{
							$str_sql = $str_sql . " and c.channel = '" . $channel . "'";
						}
					}
					if (isset($outlet_type))
					{
						if($outlet_type != '')
						{
							$str_sql = $str_sql . " and a.outlet_type = '" . $outlet_type . "'";
						}
					}
					if (isset($area))
					{
						if($area != '')
						{
							$str_sql = $str_sql . " and a.area in ('" . $area . "')";
						}
					}
					$str_sql = $str_sql . " group by a.outlet_type, a.big_code, a.area";
					$str_sql = $str_sql . " order by a.big_code";
					$str_sql = $str_sql . " ) b on a.outlet_type = b.outlet_type";
		$str_sql = $str_sql . " LEFT JOIN (";
					$str_sql = $str_sql . " select x.big_code, x.cust_code, x.cust_name, x.area, x.outlet_type, x.kode_dist, x.nama_dist, max(z.total_outlet) as DISTR";
					$str_sql = $str_sql . " from selling_out x";
					$str_sql = $str_sql . " left join area y on x.area = y.area";
					$str_sql = $str_sql . " inner join outlet z on x.big_code = z.big_code and x.outlet_type = z.outlet_type and x.area = z.area";
					$str_sql = $str_sql . " inner join channel zz on z.outlet_type = zz.outlet_type";
					$str_sql = $str_sql . " where x.tanggal between DATE_SUB(concat('" . $year . "', '".$fromdate."'), INTERVAL 11 month) and LAST_DAY(concat('" . $year . "', '".$fromdate."'))";
					if (isset($principal))
					{
						if($principal != '')
						{
							$str_sql = $str_sql . " and x.principal = '" . $principal . "'";
						}
					}
					if (isset($channel))
					{
						if($channel != '')
						{
							$str_sql = $str_sql . " and zz.channel = '" . $channel . "'";
						}
					}
					if (isset($outlet_type))
					{
						if($outlet_type != '')
						{
							$str_sql = $str_sql . " and x.outlet_type = '" . $outlet_type . "'";
						}
					}
					if (isset($area))
					{
						if($area != '')
						{
							$str_sql = $str_sql . " and x.area in ('" . $area . "')";
						}
					}
					$str_sql = $str_sql . " group by x.outlet_type, x.big_code, x.area";
					$str_sql = $str_sql . " ) c on a.outlet_type = c.outlet_type AND b.big_code = c.big_code AND b.area = c.area";
		$str_sql = $str_sql . " LEFT JOIN (";
					$str_sql = $str_sql . " select x.big_code, x.cust_code, x.cust_name, x.area, x.outlet_type, x.kode_dist, x.nama_dist, max(z.total_outlet) as AO";
					$str_sql = $str_sql . " from selling_out x";
					$str_sql = $str_sql . " left join area y on x.area = y.area";
					$str_sql = $str_sql . " inner join outlet z on x.big_code = z.big_code and x.outlet_type = z.outlet_type and x.area = z.area";
					$str_sql = $str_sql . " inner join channel zz on z.outlet_type = zz.outlet_type";
					$str_sql = $str_sql . " where month(x.tanggal) = '".$month."' and year(x.tanggal) = '".$year."'";
					if (isset($principal))
					{
						if($principal != '')
						{
							$str_sql = $str_sql . " and x.principal = '" . $principal . "'";
						}
					}
					if (isset($channel))
					{
						if($channel != '')
						{
							$str_sql = $str_sql . " and zz.channel = '" . $channel . "'";
						}
					}
					if (isset($outlet_type))
					{
						if($outlet_type != '')
						{
							$str_sql = $str_sql . " and x.outlet_type = '" . $outlet_type . "'";
						}
					}
					if (isset($area))
					{
						if($area != '')
						{
							$str_sql = $str_sql . " and x.area in ('" . $area . "')";
						}
					}
					$str_sql = $str_sql . " group by x.outlet_type, x.big_code, x.area";
					$str_sql = $str_sql . " ) d on a.outlet_type = d.outlet_type AND b.big_code = d.big_code AND b.area = d.area";
		
		$str_sql = $str_sql . " GROUP BY a.outlet_type, b.big_code";
		$str_sql = $str_sql . " ORDER BY a.id, b.big_code, b.outlet_code";

		// Flasher::setMessage('Berhasil', $str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

	public function getDistribution_OT2($direct)
	{

		$data = explode(",", $direct);

