		$outlet_type = str_replace("__", " ", $data[1]);
		$year = $data[2];
		$interval_year = $year - 1;
		$count = count($data);

		if ($count > 5)
		{
			//$area = str_replace("__", " ", $data[3]);
			$area_arr = array();
			for ($a = 4; $a <= $count-1; $a ++) {
				array_push($area_arr, $data[$a]);
