		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '3', a.qty, 0)) AS qty_mar,"; 
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '3', a.value_exc, 0)) AS val_mar,";
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '4', a.qty, 0)) AS qty_apr,";
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '4', a.value_exc, 0)) AS val_apr,";
