		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '5', a.value_exc, 0)) AS val_mei,";
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '6', a.qty, 0)) AS qty_jun,";
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '6', a.value_exc, 0)) AS val_jun,"; 
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '7', a.qty, 0)) AS qty_jul,"; 
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '7', a.value_exc, 0)) AS val_jul,"; 
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '8', a.qty, 0)) AS qty_agu,"; 
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '8', a.value_exc, 0)) AS val_agu,"; 
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '9', a.qty, 0)) AS qty_sep,"; 
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '9', a.value_exc, 0)) AS val_sep,";
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '10', a.qty, 0)) AS qty_okt,";
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '10', a.value_exc, 0)) AS val_okt,";
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '11', a.qty, 0)) AS qty_nop,";
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '11', a.value_exc, 0)) AS val_nop,";
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '12', a.qty, 0)) AS qty_des,";
		$str_sql = $str_sql . " sum(distinct if(month(a.tanggal) = '12', a.value_exc, 0)) AS val_des,";
