	public function getSellingOut_Growth_OT_Exist($direct)
	{
		$data_direct = explode(",", $direct);

		$data_ot_category = str_replace("8", "&", $data_direct[1]);

		$data_principal = $data_direct[0];
		$data_outlet_category = str_replace("__", " ", $data_ot_category);
		$data_year = $data_direct[2];
		$data_area = array();
		$data_area_count = count($data_direct);

		for ($a = 3; $a <= $data_area_count-1; $a++) 
		{
			array_push( $data_area, str_replace("__", " ", $data_direct[$a]));
		}

		if (isset($_POST['by_principal']))
		{
			$principal = $_POST['by_principal'];
		}
		elseif (isset($data_principal))
		{
			$principal = $data_principal;
		}
		else
		{
			$principal = 'JORDAN';
		}
		if (isset($_POST['by_channel']))
		{
			$channel = $_POST['by_channel'];
		}
		if (isset($_POST['by_outlet_category']))
		{
			$outlet_category = str_replace("__", " ", $_POST['by_outlet_category']);
		}
		else
		{
			$outlet_category = $data_outlet_category;
		}
		if (isset($_POST['by_outlet_type']))
		{
			$outlet_type = $_POST['by_outlet_type'];
		}
		if (isset($_POST['by_area']))
		{
			// $area = $_POST['by_area'];
			$area = implode(',', $_POST['by_area']);
			$area = str_replace(",", "','", $area);
		}
		elseif ($_SESSION['area'] != 'ALL')
		{
			$session_area = str_replace(", ", "','", $_SESSION['area']); 
			$area = $session_area;
		}
		else
		{
			$area = implode(',', $data_area);
			$area = str_replace(",", "','", $area);
		}
		if (isset($_POST['by_year']))
		{
			$year = $_POST['by_year'];
		}
		elseif (isset($data_year))
		{
			$year = $data_year;
		}
		else
		{
			$year = date('Y');
		}
		

		$year_to = $year;
		$year_from = $year_to - 1;

		$str_sql = "SELECT c.channel, c.outlet_category, so.outlet_type, so.big_code, so.cust_name, so.area, so.item_code, s.item_name,";
		$str_sql = $str_sql . " SUM(IF(YEAR(so.tanggal) = '" . $year_from . "', so.value_exc, 0)) AS 'value_from',";
		$str_sql = $str_sql . " SUM(IF(YEAR(so.tanggal) = '" . $year_to . "', so.value_exc, 0)) AS 'value_to'";
		$str_sql = $str_sql . " FROM " . $this->table_sellingout . " so";
		$str_sql = $str_sql . " INNER JOIN channel c on so.outlet_type = c.outlet_type";
		$str_sql = $str_sql . " INNER JOIN sku s on so.item_code = s.item_code";
		$str_sql = $str_sql . " WHERE so.principal = '" . $principal . "'";
		$str_sql = $str_sql . " AND YEAR(so.tanggal) IN ('" . $year_from . "', '" . $year_to . "')";
		$str_sql = $str_sql . " AND MONTH(so.tanggal) IN (select distinct month(tanggal) as bulan from selling_out where year(tanggal) = '" . $year_to . "')";

		if (isset($channel))
		{
			if($channel != '')
			{
				$str_sql = $str_sql . " AND c.channel = '" . $channel . "'";
			}
		}

		if (isset($outlet_category))
		{
			if($outlet_category != '')
			{
				$str_sql = $str_sql . " AND c.outlet_category = '" . $outlet_category . "'";
			}
		}

		if (isset($outlet_type))
		{
			if($outlet_type != '')
			{
				$str_sql = $str_sql . " AND so.outlet_type = '" . $outlet_type . "'";
			}
		}

		if (isset($area))
		{
			if($area != '' and $area != 'ALL')
			{
				$str_sql = $str_sql . " AND so.area in ('" . $area . "')";
			}
		}

		if ($_SESSION['area'] != 'ALL')
			{
				$session_area = str_replace(",", "','", $_SESSION['area']);
				$session_area = str_replace(" ", "", $session_area);

				$str_sql = $str_sql . " AND so.area in ('" . $session_area . "')";
			}

		$str_sql = $str_sql . " GROUP BY so.outlet_type, so.big_code, so.item_code";
		$str_sql = $str_sql . " HAVING value_from <> 0";
		$str_sql = $str_sql . " ORDER BY c.id, so.big_code, s.id";

		// Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

