		if (isset($_POST['by_year']))
		{
			$year = $_POST['by_year'];
		}
		elseif (isset($data_year))
		{
			$year = $data_year;
		}
		else
		{
			$year = date('Y');
		}
		

		$year_to = $year;
		$year_from = $year_to - 1;
		$month_arr = [];

		$get['month_so'] = $this->getMonth_SO_Array($year_to);
		foreach ($get['month_so'] as $row) :
			array_push($month_arr, $row['bulan']);
		endforeach;
		$month_so = implode(',', $month_arr);

		$str_sql = "SELECT c.id, c.channel, c.outlet_category, c.outlet_type, a.big_code, a.cust_name, a.area, a.item_code, b.item_name,";
		$str_sql = $str_sql . " SUM(a.value_from) AS value_from, SUM(d.value_to) AS value_to,";
		$str_sql = $str_sql . " SUM(IF(ISNULL(d.value_to), 0, d.value_to)) AS value_exist,";
		$str_sql = $str_sql . " SUM(a.value_to) - SUM(IF(ISNULL(d.value_to), 0, d.value_to)) - SUM(IF(ISNULL(e.value_noo), 0, e.value_noo)) AS value_add_sku,";
		$str_sql = $str_sql . " SUM(IF(ISNULL(e.value_noo), 0, e.value_noo)) as value_noo";
		$str_sql = $str_sql . " FROM (";
				$str_sql = $str_sql . " select so.id, so.outlet_type, so.big_code, so.cust_name, so.area, so.item_code,";
				$str_sql = $str_sql . " sum(if(year(so.tanggal) = '" . $year_from . "', so.value_exc, 0)) as 'value_from',";
				$str_sql = $str_sql . " sum(if(year(so.tanggal) = '" . $year_to . "', so.value_exc, 0)) as 'value_to'";
				$str_sql = $str_sql . " from " . $this->table_sellingout . " so";
				$str_sql = $str_sql . " inner join channel c on so.outlet_type = c.outlet_type";
				$str_sql = $str_sql . " where so.principal = '" . $principal . "'";
				$str_sql = $str_sql . " and year(so.tanggal) in ('" . $year_from . "', '" . $year_to . "')";
				$str_sql = $str_sql . " and month(so.tanggal) in (select distinct month(tanggal) as bulan from selling_out where year(tanggal) = '" . $year_to . "')";
				$str_sql = $str_sql . " and so.value_exc <> 0 ";
				$str_sql = $str_sql . " group by so.outlet_type, so.big_code, so.item_code ) a";
				
		$str_sql = $str_sql . " INNER JOIN sku b on a.item_code = b.item_code";
		$str_sql = $str_sql . " RIGHT JOIN channel c on a.outlet_type = c.outlet_type";
		$str_sql = $str_sql . " LEFT JOIN ( select so_to.id, so_to.outlet_type, so_to.big_code, so_to.cust_name, so_to.area, so_to.item_code, so_to.value_to as value_to, so_from.value_from as value_from";
					$str_sql = $str_sql . " from ( select so.id, so.outlet_type, so.big_code, so.cust_name, so.area, so.item_code, sum(so.value_exc) as value_to";
							$str_sql = $str_sql . " from " . $this->table_sellingout . " so";
							$str_sql = $str_sql . " inner join channel c on so.outlet_type = c.outlet_type";
							$str_sql = $str_sql . " where so.principal = '" . $principal . "'";
							$str_sql = $str_sql . " and year(so.tanggal) in ('" . $year_to . "')";
							$str_sql = $str_sql . " and so.value_exc <> 0";
							$str_sql = $str_sql . " group by so.outlet_type, so.big_code, so.item_code ) so_to";
							$str_sql = $str_sql . " inner join";
							$str_sql = $str_sql . " ( select so.id, so.outlet_type, so.big_code, so.cust_name, so.area, so.item_code, sum(so.value_exc) as value_from";
							$str_sql = $str_sql . " from selling_out so";
							$str_sql = $str_sql . " inner join channel c on so.outlet_type = c.outlet_type";
							$str_sql = $str_sql . " where so.principal = '" . $principal . "'";
							$str_sql = $str_sql . " and year(so.tanggal) <= '" . $year_from . "'";
							$str_sql = $str_sql . " and so.value_exc <> 0";
							$str_sql = $str_sql . " group by so.outlet_type, so.big_code, so.item_code ) so_from on so_to.outlet_type = so_from.outlet_type";

					$str_sql = $str_sql . " and so_to.big_code = so_from.big_code and so_to.item_code = so_from.item_code ) d ON a.outlet_type = d.outlet_type AND a.big_code = d.big_code AND a.item_code = d.item_code";
		$str_sql = $str_sql . " LEFT JOIN ( select so.id, so.outlet_type, so.big_code, so.item_code, sum(so.value_exc) as value_noo";
					$str_sql = $str_sql . " from " . $this->table_sellingout . " so";
					$str_sql = $str_sql . " where so.principal = '" . $principal . "'";
					$str_sql = $str_sql . " and year(so.tanggal) in ('" . $year_to . "')";
					$str_sql = $str_sql . " and so.big_code not in ( select distinct big_code";
											$str_sql = $str_sql . " from " . $this->table_sellingout;
											$str_sql = $str_sql . " where principal = '" . $principal . "'";
											$str_sql = $str_sql . " and year(tanggal) <= '" . $year_from . "'";
											$str_sql = $str_sql . " and not isnull(big_code) ) group by so.outlet_type, so.big_code, so.item_code";
					$str_sql = $str_sql . " ) e ON a.outlet_type = e.outlet_type AND a.big_code = e.big_code AND a.item_code = e.item_code";

		$str_sql = $str_sql . " WHERE c.channel <> 'DISTRIBUTOR'";

		if (isset($channel))
		{
			if($channel != '')
			{
				$str_sql = $str_sql . " AND c.channel = '" . $channel . "'";
			}
		}

		if (isset($outlet_category))
		{
			if($outlet_category != '')
			{
				$str_sql = $str_sql . " AND c.outlet_category = '" . $outlet_category . "'";
			}
		}

		if (isset($outlet_type))
		{
			if($outlet_type != '')
			{
				$str_sql = $str_sql . " AND c.outlet_type = '" . $outlet_type . "'";
			}
		}

		if (isset($area))
		{
			if($area != '' and $area != 'ALL')
			{
				$str_sql = $str_sql . " AND a.area in ('" . $area . "')";
			}
		}

		if ($_SESSION['area'] != 'ALL')
		{
			$session_area = str_replace(",", "','", $_SESSION['area']);
			$session_area = str_replace(" ", "", $session_area);

			$str_sql = $str_sql . " AND a.area in ('" . $session_area . "')";
		}

		$str_sql = $str_sql . " GROUP BY c.outlet_category, a.big_code, a.area, a.item_code";
		$str_sql = $str_sql . " HAVING value_noo <> 0";
		$str_sql = $str_sql . " ORDER BY c.id, a.area, a.big_code, b.id";

		// Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
