	public function getQtyIn_Channel2()
	{
		$get['period_so'] = $this->getMonth_SO();
		$month_so = $get['period_so']['to_month'];
		$year_so = $get['period_so']['year'];

		if (isset($_POST['by_principal']))
		{
			$principal = $_POST['by_principal'];
		}
		if (isset($_POST['by_sku']))
		{
			$sku = $_POST['by_sku'];
		}
		if (isset($_POST['by_group_sku']))
		{
			$groupsku = $_POST['by_group_sku'];
		}
		if (isset($_POST['by_distributor']))
		{
			$distributor = $_POST['by_distributor'];
		}
		if (isset($_POST['by_area']))
		{
			$area = $_POST['by_area'];
		}
		if (isset($_POST['by_island']))
		{
			$island = $_POST['by_island'];
		}

		if(isset($_POST['by_month1']))
		{
			$month1 = $_POST['by_month1'];
		}else
		{
			$month1 = '1';
		}
		if(isset($_POST['by_month2']))
		{
			$month2 = $_POST['by_month2'];
		}else
		{
			$month2 = $month_so;
		}

		if(isset($_POST['by_year']))
		{
			$year = $_POST['by_year'];
		}else
		{
			$year = $year_so;
		}

		$area = "JKT MT";

		$str_sql = "SELECT a.channel, sum(if(isnull(c.qty), b.qty, c.qty)) as qty";
		$str_sql = $str_sql . " FROM channel a";
		$str_sql = $str_sql . " LEFT JOIN";
		$str_sql = $str_sql . " (select cc.outlet_type, sum(aa.qty) as qty from selling_in aa";
		$str_sql = $str_sql . " left join sku bb on aa.item_code = bb.item_code";
		$str_sql = $str_sql . " left join outlet cc on aa.cust_code = cc.outlet_code";
		$str_sql = $str_sql . " left join area dd on cc.area = dd.area";
		$str_sql = $str_sql . " where dd.area = :area";
		$str_sql = $str_sql . " and (month(aa.tanggal) between :month1 and :month2) and year(aa.tanggal) =:year"; 

		if (isset($principal))
		{
			if($principal != '')
			{
				$str_sql = $str_sql . " and aa.principal = :principal";
			}
		}
		if (isset($sku))
		{
			if($sku != '')
			{
				$str_sql = $str_sql . " and aa.item_name = :sku";
			}
		}

		if (isset($island))
		{
			if($island != '')
			{
				$str_sql = $str_sql . " and dd.island = :island";
			}
		}
		
		if (isset($groupsku))
		{
			if($groupsku != '')
			{
				$str_sql = $str_sql . " and bb.item_group = :groupsku";
			}
		}

		$str_sql = $str_sql . " group by cc.outlet_type) b on a.outlet_type = b.outlet_type";

		$str_sql = $str_sql . " LEFT JOIN";
		$str_sql = $str_sql . " (select 'DIST' as outlet_type, sum(aa.qty) as qty from selling_in aa";
		$str_sql = $str_sql . " left join sku bb on aa.item_code = bb.item_code";
		$str_sql = $str_sql . " left join distributor cc on aa.cust_code = cc.cust_code";
		$str_sql = $str_sql . " left join area dd on cc.area = dd.area";
		$str_sql = $str_sql . " where (month(aa.tanggal) between :month1 and :month2) and year(aa.tanggal) =:year"; 

		if (isset($principal))
		{
			if($principal != '')
			{
				$str_sql = $str_sql . " and aa.principal = :principal";
			}
		}
		if (isset($sku))
		{
			if($sku != '')
			{
				$str_sql = $str_sql . " and aa.item_name = :sku";
			}
		}

		if (isset($island))
		{
			if($island != '')
			{
				$str_sql = $str_sql . " and dd.island = :island";
			}
		}
		
		if (isset($groupsku))
		{
			if($groupsku != '')
			{
				$str_sql = $str_sql . " and bb.item_group = :groupsku";
			}
		}

		$str_sql = $str_sql . " group by outlet_type) c on a.outlet_type = c.outlet_type";
		// $str_sql = $str_sql . " WHERE a.channel <> 'OFFICE'";
		$str_sql = $str_sql . " GROUP BY a.channel";
		$str_sql = $str_sql . " ORDER BY a.id asc";

		// Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		$this->db->bind('year', $year);
		$this->db->bind('month1', $month1);
		$this->db->bind('month2', $month2);
		$this->db->bind('area', $area);

		if (isset($principal) and $principal != '')
		{
			$this->db->bind('principal', $principal);
		}
		if (isset($sku) and $sku != '')
		{
			$this->db->bind('sku', $sku);
		}
		if (isset($island) and $island != '')
		{
			$this->db->bind('island', $island);
		}
		if (isset($groupsku) and $groupsku != '')
		{
			$this->db->bind('groupsku', $groupsku);
		}
		
		return $this->db->resultSet();
	}

	public function getSI_Channel_dashboard($year)
	{
		$area = "JKT MT";

		$str_sql = "SELECT a.channel, sum(b.value) as val";
		$str_sql = $str_sql . " FROM channel a";
		$str_sql = $str_sql . " LEFT JOIN";
		$str_sql = $str_sql . " (select cc.outlet_type, (sum(aa.value_exc)+sum(aa.total_diskon))/1000 as value from selling_in aa";
		$str_sql = $str_sql . " left join sku bb on aa.item_code = bb.item_code";
		$str_sql = $str_sql . " left join outlet cc on aa.cust_code = cc.outlet_code";
