	public function getQtyIn_Channel($channel)
	{
		if (isset($_POST['by_principal']))
		{
			$principal = $_POST['by_principal'];
		}
		if (isset($_POST['by_sku']))
		{
			$sku = $_POST['by_sku'];
		}
		if (isset($_POST['by_group_sku']))
		{
			$groupsku = $_POST['by_group_sku'];
		}
		if (isset($_POST['by_distributor']))
		{
			$distributor = $_POST['by_distributor'];
		}
		if (isset($_POST['by_area']))
		{
			$area = $_POST['by_area'];
		}
		if (isset($_POST['by_island']))
		{
			$island = $_POST['by_island'];
		}

		$str_sql = "SELECT d.channel, sum(a.qty) as qty_OL FROM " . $this->table_sellingin . " a";
		$str_sql = $str_sql . " inner join outlet b on a.cust_code = b.outlet_code and b.area = 'JKT MT' and year(a.tanggal) = '" . $year . "'"; 

		if (isset($principal))
		{
			if($principal != '')
			{
				$str_sql = $str_sql . " and a.principal = '" . $principal . "'";
			}
		}

		$str_sql = $str_sql . " inner join area c on b.area = c.area"; 

		if (isset($island))
		{
			if($island != '')
			{
				$str_sql = $str_sql . " and c.island = '" . $island . "'";
			}
		}

		$str_sql = $str_sql . " right join channel d on b.outlet_type = d.outlet_type";
		$str_sql = $str_sql . " left join sku e on a.item_code = e.item_code";
		
		if (isset($sku))
		{
			if($sku != '')
			{
				$str_sql = $str_sql . " and e.item_name = '" . $sku . "'";
			}
		}
		if (isset($groupsku))
		{
			if($groupsku != '')
			{
				$str_sql = $str_sql . " and e.item_group = '" . $groupsku . "'";
			}
		}

		$str_sql = $str_sql . " where d.channel = '".$channel."'";
		$str_sql = $str_sql . " group by d.channel ORDER BY c.id";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

