	public function getReportSellingOut()
	{

		if (isset($_POST['by_principal']))
		{
			$principal = $_POST['by_principal'];
		}
		if (isset($_POST['by_sku']))
		{
			$sku = $_POST['by_sku'];
		}
		if (isset($_POST['by_group_sku']))
		{
			$groupsku = $_POST['by_group_sku'];
		}
		if (isset($_POST['by_distributor']))
		{
			$distributor = $_POST['by_distributor'];
		}
		if (isset($_POST['by_area']))
		{
			$area = $_POST['by_area'];
		}
		if (isset($_POST['by_island']))
		{
			$island = $_POST['by_island'];
		}

		$str_sql = "SELECT c.id, c.channel, c.desc_type, c.outlet_type, sum(a.qty) as qty FROM " . $this->table_sellingout . " a";

		if (isset($principal))
		{
			if($principal != '')
			{
				$str_sql = $str_sql . " and a.principal = '" . $principal . "'";
			}
		}
		if (isset($sku))
		{
			if($sku != '')
			{
				$str_sql = $str_sql . " and a.item_name = '" . $sku . "'";
			}
		}
		if (isset($groupsku))
		{
			if($groupsku != '')
			{
				$str_sql = $str_sql . " and a.item_group = '" . $groupsku . "'";
			}
		}
		if (isset($distributor))
		{
			if($distributor != '')
			{
				$str_sql = $str_sql . " and a.nama_dist = '" . $distributor . "'";
			}
		}
		if (isset($area))
		{
			if($area != '')
			{
				$str_sql = $str_sql . " and a.area = '" . $area . "'";
			}
		}


		$str_sql = $str_sql . " right join channel c on a.outlet_type = c.outlet_type"; 
		$str_sql = $str_sql . " left join area d on a.area = d.area";

		if (isset($island))
		{
			if($island != '')
			{
				$str_sql = $str_sql . " where d.island = '" . $island . "'";
			}
		}

		$str_sql = $str_sql . " group by c.channel, c.outlet_type ORDER BY c.id";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

