	public function getSellingIn_Year()
	{
		if (isset($_POST['by_region']))
		{
			$region = $_POST['by_region'];
		}
		if (isset($_POST['by_area']))
		{
			$area = $_POST['by_area'];
		}
		if (isset($_POST['by_island']))
		{
			$island = $_POST['by_island'];
		}
		if(isset($_POST['by_year']))
		{
			$year = $_POST['by_year'];
		}else
		{
			$year = date('Y');
		}

		$str_sql = "SELECT a.id, a.principal, a.item_group, a.item_code, a.item_name, a.unit,";

		$str_sql = $str_sql . " b.qty_jan, b.value_jan, o.target_qty_jan, o.target_val_jan,";
		$str_sql = $str_sql . " (b.qty_jan/o.target_qty_jan)*100 as idx_qty_jan, (b.value_jan/o.target_val_jan)*100 as idx_val_jan,";
		$str_sql = $str_sql . " aa.stok_qty_jan, aa.stok_val_jan,";
		$str_sql = $str_sql . " c.qty_feb, c.value_feb, o.target_qty_feb, o.target_val_feb,";
		$str_sql = $str_sql . " (c.qty_feb/o.target_qty_feb)*100 as idx_qty_feb, (c.value_feb/o.target_val_feb)*100 as idx_val_feb,";
		$str_sql = $str_sql . " ab.stok_qty_feb, ab.stok_val_feb,";
		$str_sql = $str_sql . " d.qty_mar, d.value_mar, o.target_qty_mar, o.target_val_mar,";
		$str_sql = $str_sql . " (d.qty_mar/o.target_qty_mar)*100 as idx_qty_mar, (d.value_mar/o.target_val_mar)*100 as idx_val_mar,";
		$str_sql = $str_sql . " ac.stok_qty_mar, ac.stok_val_mar,";
		$str_sql = $str_sql . " (coalesce(b.qty_jan,0) + coalesce(c.qty_feb,0) + coalesce(d.qty_mar,0)) as qty_q1, (coalesce(b.value_jan,0) + coalesce(c.value_feb,0) + coalesce(d.value_mar,0)) as value_q1,";
		$str_sql = $str_sql . " (o.target_qty_jan + o.target_qty_feb + o.target_qty_mar) as target_qty_q1, (o.target_val_jan + o.target_val_feb + o.target_val_mar) as target_value_q1,";
		$str_sql = $str_sql . " (b.qty_jan + c.qty_feb + d.qty_mar)/(o.target_qty_jan + o.target_qty_feb + o.target_qty_mar)*100 as idx_qty_q1,";
		$str_sql = $str_sql . " (b.value_jan + c.value_feb + d.value_mar)/(o.target_val_jan + o.target_val_feb + o.target_val_mar)*100 as idx_val_q1,";

		$str_sql = $str_sql . " e.qty_apr, e.value_apr, o.target_qty_apr, o.target_val_apr,";
		$str_sql = $str_sql . " (e.qty_apr/o.target_qty_apr)*100 as idx_qty_apr, (e.value_apr/o.target_val_apr)*100 as idx_val_apr,";
		$str_sql = $str_sql . " ad.stok_qty_apr, ad.stok_val_apr,";
		$str_sql = $str_sql . " f.qty_mei, f.value_mei, o.target_qty_mei, o.target_val_mei,";
		$str_sql = $str_sql . " (f.qty_mei/o.target_qty_mei)*100 as idx_qty_mei, (f.value_mei/o.target_val_mei)*100 as idx_val_mei,";
		$str_sql = $str_sql . " ae.stok_qty_mei, ae.stok_val_mei,";
		$str_sql = $str_sql . " g.qty_jun, g.value_jun, o.target_qty_jun, o.target_val_jun,";
		$str_sql = $str_sql . " (g.qty_jun/o.target_qty_jun)*100 as idx_qty_jun, (g.value_jun/o.target_val_jun)*100 as idx_val_jun,";
		$str_sql = $str_sql . " af.stok_qty_jun, af.stok_val_jun,";
		$str_sql = $str_sql . " (coalesce(e.qty_apr,0) + coalesce(f.qty_mei,0) + coalesce(g.qty_jun,0)) as qty_q2, (coalesce(e.value_apr ,0) + coalesce(f.value_mei,0) + coalesce(g.value_jun,0)) as value_q2,";
		$str_sql = $str_sql . " (o.target_qty_apr + o.target_qty_mei + o.target_qty_jun) as target_qty_q2, (o.target_val_apr + o.target_val_mei + o.target_val_jun) as target_value_q2,";
		$str_sql = $str_sql . " (e.qty_apr + f.qty_mei + g.qty_jun)/(o.target_qty_apr + o.target_qty_mei + o.target_qty_jun)*100 as idx_qty_q2,";
		$str_sql = $str_sql . " (e.value_apr + f.value_mei + g.value_jun)/(o.target_val_apr + o.target_val_mei + o.target_val_jun)*100 as idx_val_q2,";

		$str_sql = $str_sql . " h.qty_jul, h.value_jul, o.target_qty_jul, o.target_val_jul,";
		$str_sql = $str_sql . " (h.qty_jul/o.target_qty_jul)*100 as idx_qty_jul, (h.value_jul/o.target_val_jul)*100 as idx_val_jul,";
		$str_sql = $str_sql . " ag.stok_qty_jul, ag.stok_val_jul,";
		$str_sql = $str_sql . " i.qty_agu, i.value_agu, o.target_qty_agu, o.target_val_agu,";
		$str_sql = $str_sql . " (i.qty_agu/o.target_qty_agu)*100 as idx_qty_agu, (i.value_agu/o.target_val_agu)*100 as idx_val_agu,";
		$str_sql = $str_sql . " ah.stok_qty_agu, ah.stok_val_agu,";
		$str_sql = $str_sql . " j.qty_sep, j.value_sep, o.target_qty_sep, o.target_val_sep,";
