			$str_sql = $str_sql . " (select distinct x.principal, x.item_code, sum(x.qty) as stok_qty_jul, sum(x.value)/1000 as stok_val_jul from stok x left join area y on x.area = y.area where x.tahun = '" . $year . "' and CONVERT(x.bulan, SIGNED INTEGER) = '7' and y.island = '" . $island . "' group by y.island, x.item_code) ag on a.item_code = ag.item_code";
