			$str_sql = $str_sql . " sum(if(i.bulan = 3, i.value, 0)) as  target_val_mar,";
			$str_sql = $str_sql . " sum(if(i.bulan = 4, i.qty, 0)) as target_qty_apr,";
			$str_sql = $str_sql . " sum(if(i.bulan = 4, i.value, 0)) as  target_val_apr,";
			$str_sql = $str_sql . " sum(if(i.bulan = 5, i.qty, 0)) as target_qty_mei,";
			$str_sql = $str_sql . " sum(if(i.bulan = 5, i.value, 0)) as  target_val_mei,";
			$str_sql = $str_sql . " sum(if(i.bulan = 6, i.qty, 0)) as target_qty_jun,";
			$str_sql = $str_sql . " sum(if(i.bulan = 6, i.value, 0)) as  target_val_jun,";
			$str_sql = $str_sql . " sum(if(i.bulan = 7, i.qty, 0)) as target_qty_jul,";
			$str_sql = $str_sql . " sum(if(i.bulan = 7, i.value, 0)) as  target_val_jul,";
			$str_sql = $str_sql . " sum(if(i.bulan = 8, i.qty, 0)) as target_qty_agu,";
			$str_sql = $str_sql . " sum(if(i.bulan = 8, i.value, 0)) as  target_val_agu,";
			$str_sql = $str_sql . " sum(if(i.bulan = 9, i.qty, 0)) as target_qty_sep,";
			$str_sql = $str_sql . " sum(if(i.bulan = 9, i.value, 0)) as  target_val_sep,";
			$str_sql = $str_sql . " sum(if(i.bulan = 10, i.qty, 0)) as target_qty_okt,";
			$str_sql = $str_sql . " sum(if(i.bulan = 10, i.value, 0)) as  target_val_okt,";
			$str_sql = $str_sql . " sum(if(i.bulan = 11, i.qty, 0)) as target_qty_nop,";
			$str_sql = $str_sql . " sum(if(i.bulan = 11, i.value, 0)) as  target_val_nop,";
			$str_sql = $str_sql . " sum(if(i.bulan = 12, i.qty, 0)) as target_qty_des,";
			$str_sql = $str_sql . " sum(if(i.bulan = 12, i.value, 0)) as  target_val_des";
			$str_sql = $str_sql . " from";

			$str_sql = $str_sql . " (select x.bulan, x.item_code, (x.qty + y.qty) as qty, (x.value + y.value) as value";
			$str_sql = $str_sql . " from";

			$str_sql = $str_sql . " (select distinct a.bulan, a.item_code, sum(a.qty) as qty, (sum(a.qty)*max(c.price_exc))/1000 as value";
			$str_sql = $str_sql . " from sellingout_target a";
			$str_sql = $str_sql . " inner join area b on a.area = b.area";
			$str_sql = $str_sql . " inner join pricelist c on a.item_code = c.item_code and c.valid_from <= concat(a.tahun, '-', a.bulan, '-', '01')";
			$str_sql = $str_sql . " where a.area = 'JKT MT' and a.tahun = '" . $year . "'";
			$str_sql = $str_sql . " group by a.bulan, a.item_code) x";

			$str_sql = $str_sql . " inner join";

			$str_sql = $str_sql . " (select distinct a.bulan, a.item_code, sum(a.qty) as qty, (sum(a.qty)*max(c.dist_exc))/1000 as value";
			$str_sql = $str_sql . " from sellingout_target a";
			$str_sql = $str_sql . " inner join (select distinct area from distributor) b on a.area = b.area";
			$str_sql = $str_sql . " inner join pricelist c on a.item_code = c.item_code and c.valid_from <= concat(a.tahun, '-', a.bulan, '-', '01')";
			$str_sql = $str_sql . " inner join area d on a.area = d.area";
			$str_sql = $str_sql . " where a.tahun = '" . $year . "'";
			$str_sql = $str_sql . " group by a.bulan, a.item_code) y on x.bulan = y.bulan and x.item_code = y.item_code";

			$str_sql = $str_sql . " group by x.bulan, x.item_code) i";

			$str_sql = $str_sql . " group by i.item_code) o on a.item_code = o.item_code";
			//end target

			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_jan, sum(value)/1000 as stok_val_jan from stok where tahun = '" . $year . "' and CONVERT(bulan, SIGNED INTEGER) = '1' group by principal, item_code) aa on a.item_code = aa.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_feb, sum(value)/1000 as stok_val_feb from stok where tahun = '" . $year . "' and CONVERT(bulan, SIGNED INTEGER) = '2' group by principal, item_code) ab on a.item_code = ab.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_mar, sum(value)/1000 as stok_val_mar from stok where tahun = '" . $year . "' and CONVERT(bulan, SIGNED INTEGER) = '3' group by principal, item_code) ac on a.item_code = ac.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_apr, sum(value)/1000 as stok_val_apr from stok where tahun = '" . $year . "' and CONVERT(bulan, SIGNED INTEGER) = '4' group by principal, item_code) ad on a.item_code = ad.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_mei, sum(value)/1000 as stok_val_mei from stok where tahun = '" . $year . "' and CONVERT(bulan, SIGNED INTEGER) = '5' group by principal, item_code) ae on a.item_code = ae.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_jun, sum(value)/1000 as stok_val_jun from stok where tahun = '" . $year . "' and CONVERT(bulan, SIGNED INTEGER) = '6' group by principal, item_code) af on a.item_code = af.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_jul, sum(value)/1000 as stok_val_jul from stok where tahun = '" . $year . "' and CONVERT(bulan, SIGNED INTEGER) = '7' group by principal, item_code) ag on a.item_code = ag.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_agu, sum(value)/1000 as stok_val_agu from stok where tahun = '" . $year . "' and CONVERT(bulan, SIGNED INTEGER) = '8' group by principal, item_code) ah on a.item_code = ah.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_sep, sum(value)/1000 as stok_val_sep from stok where tahun = '" . $year . "' and CONVERT(bulan, SIGNED INTEGER) = '9' group by principal, item_code) ai on a.item_code = ai.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_okt, sum(value)/1000 as stok_val_okt from stok where tahun = '" . $year . "' and CONVERT(bulan, SIGNED INTEGER) = '10' group by principal, item_code) aj on a.item_code = aj.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_nop, sum(value)/1000 as stok_val_nop from stok where tahun = '" . $year . "' and CONVERT(bulan, SIGNED INTEGER) = '11' group by principal, item_code) ak on a.item_code = ak.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_des, sum(value)/1000 as stok_val_des from stok where tahun = '" . $year . "' and CONVERT(bulan, SIGNED INTEGER) = '12' group by principal, item_code) al on a.item_code = al.item_code";
		}

		$str_sql = $str_sql . " group by a.principal, a.item_group, a.item_code";
		$str_sql = $str_sql . " order by a.id, a.principal, a.item_group";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

