		$str_sql = $str_sql . " ai.stok_qty_sep, ai.stok_val_sep,";
		$str_sql = $str_sql . " (coalesce(h.qty_jul,0) + coalesce(i.qty_agu,0) + coalesce(j.qty_sep,0)) as qty_q3, (coalesce(h.value_jul,0) + coalesce(i.value_agu,0) + coalesce(j.value_sep,0)) as value_q3,";
		$str_sql = $str_sql . " (o.target_qty_jul + o.target_qty_agu + o.target_qty_sep) as target_qty_q3, (o.target_val_jul + o.target_val_agu + o.target_val_sep) as target_value_q3,";
		$str_sql = $str_sql . " (h.qty_jul + i.qty_agu + j.qty_sep)/(o.target_qty_jul + o.target_qty_agu + o.target_qty_sep)*100 as idx_qty_q3,";
		$str_sql = $str_sql . " (h.value_jul + i.value_agu + j.value_sep)/(o.target_val_jul + o.target_val_agu + o.target_val_sep)*100 as idx_val_q3,";

		$str_sql = $str_sql . " k.qty_okt, k.value_okt, o.target_qty_okt, o.target_val_okt,";
		$str_sql = $str_sql . " (k.qty_okt/o.target_qty_okt)*100 as idx_qty_okt, (k.value_okt/o.target_val_okt)*100 as idx_val_okt,";
		$str_sql = $str_sql . " aj.stok_qty_okt, aj.stok_val_okt,";
