		$str_sql = $str_sql . " al.stok_qty_des, al.stok_val_des,";
		$str_sql = $str_sql . " (coalesce(k.qty_okt,0) + coalesce(l.qty_nop,0) + coalesce(m.qty_des,0)) as qty_q4, (coalesce(k.value_okt,0) + coalesce(l.value_nop,0) + coalesce(m.value_des,0)) as value_q4,";
		$str_sql = $str_sql . " (o.target_qty_okt + o.target_qty_nop + o.target_qty_des) as target_qty_q4, (o.target_val_okt + o.target_val_nop + o.target_val_des) as target_value_q4,";
		$str_sql = $str_sql . " (k.qty_okt + l.qty_nop + m.qty_des)/(o.target_val_okt + o.target_val_nop + o.target_val_des)*100 as idx_qty_q4,";
		$str_sql = $str_sql . " (k.value_okt + l.value_nop + m.value_des)/(o.target_val_okt + o.target_val_nop + o.target_val_des)*100 as idx_val_q4,";
		$str_sql = $str_sql . " n.qty_total, n.value_total,(n.qty_total/12) as qty_avg, (n.value_total/12) as value_avg";

		$str_sql = $str_sql . " from sku a";
