			$str_sql = $str_sql . " inner join outlet c on a.cust_code = c.outlet_code and c.area = 'JKT MT'";
			$str_sql = $str_sql . " left join area d on c.area = d.area";
			$str_sql = $str_sql . " where year(a.tanggal) = :year"; 
			$str_sql = $str_sql . " group by a.principal, b.item_group, a.item_code";
			$str_sql = $str_sql . " union all";
			$str_sql = $str_sql . " select distinct a.principal, b.item_group, a.item_code, sum(a.qty) as qty_total, (sum(a.value_exc)+sum(a.total_diskon))/1000 as value_total";
			$str_sql = $str_sql . " from selling_in a";
			$str_sql = $str_sql . " inner join sku b on a.item_code = b.item_code";
			$str_sql = $str_sql . " inner join distributor c on a.cust_code = c.cust_code";
			$str_sql = $str_sql . " left join area d on c.area = d.area";
			$str_sql = $str_sql . " where year(a.tanggal) = :year"; 
			$str_sql = $str_sql . " group by a.principal, b.item_group, a.item_code) x";
			$str_sql = $str_sql . " group by x.principal, x.item_group, x.item_code)";
			$str_sql = $str_sql . " n on a.item_code = n.item_code";

			//target
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct i.item_code,";
			$str_sql = $str_sql . " sum(if(i.bulan = 1, i.qty, 0)) as target_qty_jan,";
			$str_sql = $str_sql . " sum(if(i.bulan = 1, i.value, 0)) as  target_val_jan,";
			$str_sql = $str_sql . " sum(if(i.bulan = 2, i.qty, 0)) as target_qty_feb,";
			$str_sql = $str_sql . " sum(if(i.bulan = 2, i.value, 0)) as  target_val_feb,";
			$str_sql = $str_sql . " sum(if(i.bulan = 3, i.qty, 0)) as target_qty_mar,";
			$str_sql = $str_sql . " sum(if(i.bulan = 3, i.value, 0)) as  target_val_mar,";
			$str_sql = $str_sql . " sum(if(i.bulan = 4, i.qty, 0)) as target_qty_apr,";
			$str_sql = $str_sql . " sum(if(i.bulan = 4, i.value, 0)) as  target_val_apr,";
			$str_sql = $str_sql . " sum(if(i.bulan = 5, i.qty, 0)) as target_qty_mei,";
			$str_sql = $str_sql . " sum(if(i.bulan = 5, i.value, 0)) as  target_val_mei,";
			$str_sql = $str_sql . " sum(if(i.bulan = 6, i.qty, 0)) as target_qty_jun,";
			$str_sql = $str_sql . " sum(if(i.bulan = 6, i.value, 0)) as  target_val_jun,";
			$str_sql = $str_sql . " sum(if(i.bulan = 7, i.qty, 0)) as target_qty_jul,";
			$str_sql = $str_sql . " sum(if(i.bulan = 7, i.value, 0)) as  target_val_jul,";
			$str_sql = $str_sql . " sum(if(i.bulan = 8, i.qty, 0)) as target_qty_agu,";
			$str_sql = $str_sql . " sum(if(i.bulan = 8, i.value, 0)) as  target_val_agu,";
			$str_sql = $str_sql . " sum(if(i.bulan = 9, i.qty, 0)) as target_qty_sep,";
			$str_sql = $str_sql . " sum(if(i.bulan = 9, i.value, 0)) as  target_val_sep,";
			$str_sql = $str_sql . " sum(if(i.bulan = 10, i.qty, 0)) as target_qty_okt,";
			$str_sql = $str_sql . " sum(if(i.bulan = 10, i.value, 0)) as  target_val_okt,";
			$str_sql = $str_sql . " sum(if(i.bulan = 11, i.qty, 0)) as target_qty_nop,";
			$str_sql = $str_sql . " sum(if(i.bulan = 11, i.value, 0)) as  target_val_nop,";
			$str_sql = $str_sql . " sum(if(i.bulan = 12, i.qty, 0)) as target_qty_des,";
			$str_sql = $str_sql . " sum(if(i.bulan = 12, i.value, 0)) as  target_val_des";
			$str_sql = $str_sql . " from";

			$str_sql = $str_sql . " (select x.bulan, x.item_code, sum(x.qty) as qty, sum(x.value) as value";
			$str_sql = $str_sql . " from";

			$str_sql = $str_sql . " (select distinct a.bulan, a.item_code, sum(a.qty) as qty, (sum(a.qty)*max(c.mt_exc))/1000 as value";
			$str_sql = $str_sql . " from sellingout_target a";
			$str_sql = $str_sql . " inner join (select distinct area from distributor) b on a.area = b.area and b.area = 'JKT MT'";
            $str_sql = $str_sql . " inner join pricelist c on a.item_code = c.item_code and c.valid_from <= concat(a.tahun, '-', a.bulan, '-', '01')";
			$str_sql = $str_sql . " inner join area d on a.area = d.area";
			$str_sql = $str_sql . " where a.tahun = :year";
			$str_sql = $str_sql . " group by a.bulan, a.item_code";

			$str_sql = $str_sql . " union all";

			$str_sql = $str_sql . " select distinct a.bulan, a.item_code, sum(a.qty) as qty, (sum(a.qty)*max(c.dist_exc))/1000 as value";
			$str_sql = $str_sql . " from sellingout_target a";
			$str_sql = $str_sql . " inner join (select distinct area from distributor) b on a.area = b.area and b.area <> 'JKT MT'";
			$str_sql = $str_sql . " inner join pricelist c on a.item_code = c.item_code and c.valid_from <= concat(a.tahun, '-', a.bulan, '-', '01')";
			$str_sql = $str_sql . " inner join area d on a.area = d.area";
			$str_sql = $str_sql . " where a.tahun = :year";
			$str_sql = $str_sql . " group by a.bulan, a.item_code) x";

			$str_sql = $str_sql . " group by x.bulan, x.item_code) i";

			$str_sql = $str_sql . " group by i.item_code) o on a.item_code = o.item_code";
			//end target

			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_jan, sum(value)/1000 as stok_val_jan from stok where tahun = :year and CONVERT(bulan, SIGNED INTEGER) = '1' group by principal, item_code) aa on a.item_code = aa.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_feb, sum(value)/1000 as stok_val_feb from stok where tahun = :year and CONVERT(bulan, SIGNED INTEGER) = '2' group by principal, item_code) ab on a.item_code = ab.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_mar, sum(value)/1000 as stok_val_mar from stok where tahun = :year and CONVERT(bulan, SIGNED INTEGER) = '3' group by principal, item_code) ac on a.item_code = ac.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_apr, sum(value)/1000 as stok_val_apr from stok where tahun = :year and CONVERT(bulan, SIGNED INTEGER) = '4' group by principal, item_code) ad on a.item_code = ad.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_mei, sum(value)/1000 as stok_val_mei from stok where tahun = :year and CONVERT(bulan, SIGNED INTEGER) = '5' group by principal, item_code) ae on a.item_code = ae.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_jun, sum(value)/1000 as stok_val_jun from stok where tahun = :year and CONVERT(bulan, SIGNED INTEGER) = '6' group by principal, item_code) af on a.item_code = af.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_jul, sum(value)/1000 as stok_val_jul from stok where tahun = :year and CONVERT(bulan, SIGNED INTEGER) = '7' group by principal, item_code) ag on a.item_code = ag.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_agu, sum(value)/1000 as stok_val_agu from stok where tahun = :year and CONVERT(bulan, SIGNED INTEGER) = '8' group by principal, item_code) ah on a.item_code = ah.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_sep, sum(value)/1000 as stok_val_sep from stok where tahun = :year and CONVERT(bulan, SIGNED INTEGER) = '9' group by principal, item_code) ai on a.item_code = ai.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_okt, sum(value)/1000 as stok_val_okt from stok where tahun = :year and CONVERT(bulan, SIGNED INTEGER) = '10' group by principal, item_code) aj on a.item_code = aj.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_nop, sum(value)/1000 as stok_val_nop from stok where tahun = :year and CONVERT(bulan, SIGNED INTEGER) = '11' group by principal, item_code) ak on a.item_code = ak.item_code";
			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct principal, item_code, sum(qty) as stok_qty_des, sum(value)/1000 as stok_val_des from stok where tahun = :year and CONVERT(bulan, SIGNED INTEGER) = '12' group by principal, item_code) al on a.item_code = al.item_code";
		}

		$str_sql = $str_sql . " group by a.principal, a.item_group, a.item_code";
		$str_sql = $str_sql . " order by a.id, a.principal, a.item_group";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

	public function getSellingOut_Month()
	{
		if (isset($_POST['by_dist']))
		{
			$kode_dist = $_POST['by_dist'];
		}
		if (isset($_POST['by_year']))
		{
			$year = $_POST['by_year'];
		}else
		{
			$year = date('Y');
		}
		if (isset($_POST['by_month']))
		{
			$month = $_POST['by_month'];
		}else
		{
			$month = date('m');
		}

		$last_month = (int)$month - 1;

		$str_sql = "SELECT a.id, a.principal, a.item_group, a.item_code, a.item_name, a.unit,";

		$str_sql = $str_sql . " b.qty_w1, b.value_w1, b.qty_w2, b.value_w2, b.qty_w3, b.value_w3, b.qty_w4, b.value_w4, b.qty_w5, b.value_w5, b.qty_w6, b.value_w6,";
		$str_sql = $str_sql . " b.qty_total, b.value_total, c.target_qty, c.target_value,";
		$str_sql = $str_sql . " (d.stok_qty + IFNULL(e.sellingin_qty, 0) - b.qty_total) as ending_qty, (d.stok_value + IFNULL(e.sellingin_value, 0) - b.value_total) as ending_value,";
		$str_sql = $str_sql . " f.transit_qty, f.transit_value";

		$str_sql = $str_sql . " from sku a";
		$str_sql = $str_sql . " left join";

		if ($_SESSION['area'] != 'ALL')
		{
			$session_area = str_replace(",", "','", $_SESSION['area']);
			$session_area = str_replace(" ", "", $session_area);

			$str_sql = $str_sql . " (select distinct x.principal, x.item_group, x.item_code,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '1', qty, 0)) as qty_w1,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '1', x.value_exc, 0)) as value_w1,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '2', qty, 0)) as qty_w2,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '2', x.value_exc, 0)) as value_w2,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '3', qty, 0)) as qty_w3,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '3', x.value_exc, 0)) as value_w3,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '4', qty, 0)) as qty_w4,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '4', x.value_exc, 0)) as value_w4,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '5', qty, 0)) as qty_w5,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '5', x.value_exc, 0)) as value_w5,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '6', qty, 0)) as qty_w6,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '6', x.value_exc, 0)) as value_w6,";
			$str_sql = $str_sql . " sum(x.qty) as qty_total, sum(x.value_exc) as value_total";
			$str_sql = $str_sql . " from selling_out x";
			$str_sql = $str_sql . " left join area y on x.area = y.area"; 
			$str_sql = $str_sql . " where year(x.tanggal) = '" . $year . "' and month(x.tanggal) = '" . $month . "' and x.area in ('" . $session_area . "')";
			$str_sql = $str_sql . " group by x.principal, x.item_group, x.item_code) b on a.item_code = b.item_code";

			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct x.principal, x.area, x.item_code, sum(x.qty) as target_qty, sum(x.value) as target_value";
			$str_sql = $str_sql . " from sellingout_target x";
			$str_sql = $str_sql . " left join area y on x.area = y.area"; 
			$str_sql = $str_sql . " where x.tahun = '" . $year . "' and x.bulan = '" . $month . "' and x.area in ('" . $session_area . "')";
			$str_sql = $str_sql . " group by x.principal, x.area, x.item_code) c on a.item_code = c.item_code";

			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct x.principal, x.area, x.item_code, sum(x.qty) as stok_qty, sum(x.value) as stok_value";
			$str_sql = $str_sql . " from stok x ";
			$str_sql = $str_sql . " left join area y on x.area = y.area";
			$str_sql = $str_sql . " where x.tahun = '" . $year . "' and x.bulan = '" . $last_month . "' and x.area in ('" . $session_area . "')";
			$str_sql = $str_sql . " group by x.principal, x.area, x.item_code) d on a.item_code = d.item_code";

			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct a.principal, b.item_group, a.item_code, sum(a.qty) as sellingin_qty, (sum(a.value_exc + a.total_diskon)) as sellingin_value";
			$str_sql = $str_sql . " from selling_in a";
			$str_sql = $str_sql . " inner join sku b on a.item_code = b.item_code";
			$str_sql = $str_sql . " inner join distributor c on a.cust_code = c.cust_code and c.area <> 'OTHERS'";
			$str_sql = $str_sql . " left join area d on c.area = d.area";
