			$str_sql = $str_sql . " group by a.principal, d.area, a.item_code) e on a.item_code = e.item_code";

			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct a.principal, b.item_group, a.item_code, sum(a.qty) as transit_qty, (sum(a.value_exc + a.total_diskon)) as transit_value";
			$str_sql = $str_sql . " from selling_in a";
			$str_sql = $str_sql . " inner join sku b on a.item_code = b.item_code";
			$str_sql = $str_sql . " inner join distributor c on a.cust_code = c.cust_code and c.area <> 'OTHERS'";
			$str_sql = $str_sql . " left join area d on c.area = d.area";
			$str_sql = $str_sql . " where year(a.tanggal) = '" . $year . "' and month(a.tanggal) = '" . $month . "' and datediff(current_date(), a.tanggal) < c.lead_time and d.area in ('" . $session_area . "')";
			$str_sql = $str_sql . " group by a.principal, d.area, a.item_code) f on a.item_code = f.item_code";
		}
		else
		{
			$str_sql = $str_sql . " (select distinct x.principal, x.item_group, x.item_code,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '1', qty, 0)) as qty_w1,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '1', x.value_exc, 0)) as value_w1,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '2', qty, 0)) as qty_w2,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '2', x.value_exc, 0)) as value_w2,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '3', qty, 0)) as qty_w3,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '3', x.value_exc, 0)) as value_w3,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '4', qty, 0)) as qty_w4,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '4', x.value_exc, 0)) as value_w4,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '5', qty, 0)) as qty_w5,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '5', x.value_exc, 0)) as value_w5,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '6', qty, 0)) as qty_w6,";
			$str_sql = $str_sql . " sum( if( WEEK(x.tanggal, 2) - WEEK(x.tanggal - INTERVAL DAY(x.tanggal)-1 DAY, 2) + 1 = '6', x.value_exc, 0)) as value_w6,";
			$str_sql = $str_sql . " sum(x.qty) as qty_total, sum(x.value_exc) as value_total";
			$str_sql = $str_sql . " from selling_out x";
			$str_sql = $str_sql . " left join area y on x.area = y.area"; 
			$str_sql = $str_sql . " where year(x.tanggal) = '" . $year . "' and month(x.tanggal) = '" . $month . "' and x.area in (select area from distributor where cust_code = '".$kode_dist."')";
			$str_sql = $str_sql . " group by x.principal, x.item_group, x.item_code) b on a.item_code = b.item_code";

			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct x.principal, x.area, x.item_code, sum(x.qty) as target_qty, sum(x.value) as target_value";
			$str_sql = $str_sql . " from sellingout_target x";
			$str_sql = $str_sql . " left join area y on x.area = y.area"; 
			$str_sql = $str_sql . " where x.tahun = '" . $year . "' and x.bulan = '" . $month . "' and x.area in (select area from distributor where cust_code = '".$kode_dist."')";
			$str_sql = $str_sql . " group by x.principal, x.area, x.item_code) c on a.item_code = c.item_code";

			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct x.principal, x.area, x.item_code, sum(x.qty) as stok_qty, sum(x.value) as stok_value";
			$str_sql = $str_sql . " from stok x ";
			$str_sql = $str_sql . " left join area y on x.area = y.area";
			$str_sql = $str_sql . " where x.tahun = '" . $year . "' and x.bulan = '" . $last_month . "' and x.area in (select area from distributor where cust_code = '".$kode_dist."')";
			$str_sql = $str_sql . " group by x.principal, x.area, x.item_code) d on a.item_code = d.item_code";

			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct a.principal, b.item_group, a.item_code, sum(a.qty) as sellingin_qty, (sum(a.value_exc + a.total_diskon)) as sellingin_value";
			$str_sql = $str_sql . " from selling_in a";
			$str_sql = $str_sql . " inner join sku b on a.item_code = b.item_code";
			$str_sql = $str_sql . " inner join distributor c on a.cust_code = c.cust_code and c.area <> 'OTHERS'";
			$str_sql = $str_sql . " left join area d on c.area = d.area";
			$str_sql = $str_sql . " where year(a.tanggal) = '" . $year . "' and month(a.tanggal) = '" . $month . "' and datediff(current_date(), a.tanggal) > c.lead_time and d.area in (select area from distributor where cust_code = '".$kode_dist."')";
			$str_sql = $str_sql . " group by a.principal, d.area, a.item_code) e on a.item_code = e.item_code";

			$str_sql = $str_sql . " left join";
			$str_sql = $str_sql . " (select distinct a.principal, b.item_group, a.item_code, sum(a.qty) as transit_qty, (sum(a.value_exc + a.total_diskon)) as transit_value";
			$str_sql = $str_sql . " from selling_in a";
			$str_sql = $str_sql . " inner join sku b on a.item_code = b.item_code";
			$str_sql = $str_sql . " inner join distributor c on a.cust_code = c.cust_code and c.area <> 'OTHERS'";
			$str_sql = $str_sql . " left join area d on c.area = d.area";
			$str_sql = $str_sql . " where year(a.tanggal) = '" . $year . "' and month(a.tanggal) = '" . $month . "' and datediff(current_date(), a.tanggal) < c.lead_time and d.area in (select area from distributor where cust_code = '".$kode_dist."')";
			$str_sql = $str_sql . " group by a.principal, d.area, a.item_code) f on a.item_code = f.item_code";
		}


		$str_sql = $str_sql . " inner join principal g on a.principal = g.principal";
		$str_sql = $str_sql . " group by a.principal, a.item_group, a.item_code";
		$str_sql = $str_sql . " order by g.id, a.id, a.principal, a.item_group";

		//Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

	public function getSellingOut_CMO()
	{
		if (isset($_POST['by_dist']))
		{
			$kode_dist = $_POST['by_dist'];
		}
		if (isset($_POST['by_year']))
		{
			$year = $_POST['by_year'];
		}else
		{
			$get['period_si'] = $this->getMonth_SO();
			$year = $get['period_si']['year'];
		}
		if (isset($_POST['by_month']))
		{
			$month = $_POST['by_month'];
		}else
		{
			$get['period_si'] = $this->getMonth_SO();
			$month = $get['period_si']['to_month'];
		}

		if((int)$month > 1)
		{
			$last_month = (int)$month - 1;
			$last_year = $year;
		}
		else
		{
			$last_month = 12;
			$last_year = $year - 1;
		}
		// $last_month = (int)$month - 1;
		$last_month_2 = (int)$last_month - 1;
		$last_month_3 = (int)$last_month - 2;

		$str_sql = "SELECT a.id, a.principal, a.item_group, a.item_code, a.item_name, a.unit, h.dist_exc,";

		$str_sql = $str_sql . " (IFNULL(d.stok_qty, 0) + IFNULL(e.sellingin_qty, 0) - IFNULL(b.qty_total, 0)) as ending_qty, (IFNULL(d.stok_value, 0) + IFNULL(e.sellingin_value, 0) - IFNULL(b.value_total, 0)) as ending_value,";
