				$str_sql = $str_sql . " left join area z on x.area = z.area";
				$str_sql = $str_sql . " where x.tanggal between DATE_SUB(concat('" . $last_year . "', '-','" . $last_month . "','-1'), INTERVAL 2 month) and LAST_DAY(concat('" . $last_year . "', '-','" . $last_month . "','-1'))";
				$str_sql = $str_sql . " group by x.principal, x.item_group, x.item_code) i on a.item_code = i.item_code";

				$str_sql = $str_sql . " LEFT JOIN";
				$str_sql = $str_sql . " (select item_code, unit_from, unit_to, multiply, divide, (multiply/divide) as unit_conversion";
				$str_sql = $str_sql . " from sku_conversion";
				$str_sql = $str_sql . " where unit_to = 'CARTON') j on a.item_code = j.item_code";
			}
			
		}

		$str_sql = $str_sql . " INNER JOIN sku_group k on a.item_group = k.item_group";
		$str_sql = $str_sql . " GROUP BY a.principal, a.item_group, a.item_code";
		$str_sql = $str_sql . " ORDER BY g.id, k.group_id, a.id, a.principal, a.item_group";

		// Flasher::setMessage('Berhasil',$str_sql,'success');
		// Flasher::setMessage('Berhasil', $last_year . ' - ' . $last_month ,'success');
		// Flasher::setMessage('Berhasil', $year . ' - ' . $month ,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

	public function getSellingOut_Year()
	{
		if (isset($_POST['by_region']))
		{
			$region = $_POST['by_region'];
		}
		if (isset($_POST['by_area']))
		{
			$area = implode(',', $_POST['by_area']);
			$area = str_replace(",", "','", $area);;
		}
		elseif ($_SESSION['area'] != 'ALL')
		{
			$session_area = str_replace(", ", "','", $_SESSION['area']); 
			$area = $session_area;
		}
		if (isset($_POST['by_island']))
		{
			$island = $_POST['by_island'];
		}
		if (isset($_POST['by_year']))
		{
			$year = $_POST['by_year'];
		}else
		{
			$year = date('Y');
		}

		$str_sql = "SELECT a.id, a.principal, a.item_group, a.item_code, a.item_name, a.unit,";

		$str_sql = $str_sql . " b.qty_jan, b.value_jan, c.target_qty_jan, c.target_val_jan,";
		$str_sql = $str_sql . " (b.qty_jan/c.target_qty_jan)*100 as idx_qty_jan, (b.value_jan/c.target_val_jan)*100 as idx_val_jan, d.stok_qty_jan, d.stok_val_jan,";
		$str_sql = $str_sql . " b.qty_feb, b.value_feb, c.target_qty_feb, c.target_val_feb,";
		$str_sql = $str_sql . " (b.qty_feb/c.target_qty_feb)*100 as idx_qty_feb, (b.value_feb/c.target_val_feb)*100 as idx_val_feb, d.stok_qty_feb, d.stok_val_feb,";
		$str_sql = $str_sql . " b.qty_mar, b.value_mar, c.target_qty_mar, c.target_val_mar,";
		$str_sql = $str_sql . " (b.qty_mar/c.target_qty_mar)*100 as idx_qty_mar, (b.value_mar/c.target_val_mar)*100 as idx_val_mar, d.stok_qty_mar, d.stok_val_mar,";
		$str_sql = $str_sql . " (coalesce(b.qty_jan,0) + coalesce(b.qty_feb,0) + coalesce(b.qty_mar,0)) as qty_q1, (coalesce(b.value_jan,0) + coalesce(b.value_feb,0) + coalesce(b.value_mar,0)) as value_q1,";
		$str_sql = $str_sql . " (c.target_qty_jan + c.target_qty_feb + c.target_qty_mar) as target_qty_q1, (c.target_val_jan + c.target_val_feb + c.target_val_mar) as target_value_q1,";
		$str_sql = $str_sql . " (b.qty_jan + b.qty_feb + b.qty_mar)/(c.target_qty_jan + c.target_qty_feb + c.target_qty_mar)*100 as idx_qty_q1,";
		$str_sql = $str_sql . " (b.value_jan + b.value_feb + b.value_mar)/(c.target_val_jan + c.target_val_feb + c.target_val_mar)*100 as idx_val_q1,";

		$str_sql = $str_sql . " b.qty_apr, b.value_apr, c.target_qty_apr, c.target_val_apr,";
		$str_sql = $str_sql . " (b.qty_apr/c.target_qty_apr)*100 as idx_qty_apr, (b.value_apr/c.target_val_apr)*100 as idx_val_apr, d.stok_qty_apr, d.stok_val_apr,"; 
		$str_sql = $str_sql . " b.qty_mei, b.value_mei, c.target_qty_mei, c.target_val_mei,"; 
		$str_sql = $str_sql . " (b.qty_mei/c.target_qty_mei)*100 as idx_qty_mei, (b.value_mei/c.target_val_mei)*100 as idx_val_mei, d.stok_qty_mei, d.stok_val_mei,"; 
		$str_sql = $str_sql . " b.qty_jun, b.value_jun, c.target_qty_jun as target_qty_jun, c.target_val_jun as target_val_jun,"; 
		$str_sql = $str_sql . " (b.qty_jun/c.target_qty_jun)*100 as idx_qty_jun, (b.value_jun/c.target_val_jun)*100 as idx_val_jun, d.stok_qty_jun, d.stok_val_jun,"; 
		$str_sql = $str_sql . " (coalesce(b.qty_apr,0) + coalesce(b.qty_mei,0) + coalesce(b.qty_jun,0)) as qty_q2, (coalesce(b.value_apr ,0) + coalesce(b.value_mei,0) + coalesce(b.value_jun,0)) as value_q2,"; 
		$str_sql = $str_sql . " (c.target_qty_apr + c.target_qty_mei + c.target_qty_jun) as target_qty_q2, (c.target_val_apr + c.target_val_mei + c.target_val_jun) as target_value_q2,"; 
		$str_sql = $str_sql . " (b.qty_apr + b.qty_mei + b.qty_jun)/(c.target_qty_apr + c.target_qty_mei + c.target_qty_jun)*100 as idx_qty_q2,"; 
		$str_sql = $str_sql . " (b.value_apr + b.value_mei + b.value_jun)/(c.target_val_apr + c.target_val_mei + c.target_val_jun)*100 as idx_val_q2,";

		$str_sql = $str_sql . " b.qty_jul, b.value_jul, c.target_qty_jul, c.target_val_jul,";
