		$str_sql = $str_sql . " (b.qty_jul + b.qty_agu + b.qty_sep)/(c.target_qty_jul + c.target_qty_agu + c.target_qty_sep)*100 as idx_qty_q3,"; 
		$str_sql = $str_sql . " (b.value_jul + b.value_agu + b.value_sep)/(c.target_val_jul + c.target_val_agu + c.target_val_sep)*100 as idx_val_q3,";

		$str_sql = $str_sql . " b.qty_okt, b.value_okt, c.target_qty_okt, c.target_val_okt,";
		$str_sql = $str_sql . " (b.qty_okt/c.target_qty_okt)*100 as idx_qty_okt, (b.value_okt/c.target_val_okt)*100 as idx_val_okt, d.stok_qty_okt, d.stok_val_okt,"; 
		$str_sql = $str_sql . " b.qty_nop, b.value_nop, c.target_qty_nop, c.target_val_nop,";
		$str_sql = $str_sql . " (b.qty_nop/c.target_qty_nop)*100 as idx_qty_nop, (b.value_nop/c.target_val_nop)*100 as idx_val_nop, d.stok_qty_nop, d.stok_val_nop,"; 
		$str_sql = $str_sql . " b.qty_des, b.value_des, c.target_qty_des, c.target_val_des,"; 
		$str_sql = $str_sql . " (b.qty_des/c.target_qty_des)*100 as idx_qty_des, (b.value_des/c.target_val_des)*100 as idx_val_des, d.stok_qty_des, d.stok_val_des,"; 
		$str_sql = $str_sql . " (coalesce(b.qty_okt,0) + coalesce(b.qty_nop,0) + coalesce(b.qty_des,0)) as qty_q4,"; 
