		$str_sql = $str_sql . " (b.qty_okt + b.qty_nop + b.qty_des)/(c.target_qty_okt + c.target_qty_nop + c.target_qty_des)*100 as idx_qty_q4,"; 
		$str_sql = $str_sql . " (b.value_okt + b.value_nop + b.value_des)/(c.target_val_okt + c.target_val_nop + c.target_val_des)*100 as idx_val_q4,"; 
		$str_sql = $str_sql . " b.qty_total, b.value_total,(b.qty_total/12) as qty_avg, (b.value_total/12) as value_avg";

		$str_sql = $str_sql . " from sku a";
		$str_sql = $str_sql . " left join";

