				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '12', qty, 0)) as stok_qty_des,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '12', x.value, 0)) as stok_val_des";
				$str_sql = $str_sql . " from stok x ";
				$str_sql = $str_sql . " left join area y on x.area = y.area";
				$str_sql = $str_sql . " where x.tahun = '" . $year . "'";
				$str_sql = $str_sql . " group by x.principal, x.area, x.item_code) d on a.item_code = d.item_code";
			}

		}

		$str_sql = $str_sql . " inner join principal e on a.principal = e.principal";
		$str_sql = $str_sql . " inner join sku_group f on a.item_group = f.item_group";
		$str_sql = $str_sql . " inner join sku_category g on a.item_category = g.item_category";
		$str_sql = $str_sql . " group by a.principal, a.item_group, a.item_code";
		$str_sql = $str_sql . " order by e.id, g.id, a.id";

		// Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

