				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '11', qty, 0)) as target_qty_nop,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '11', x.value, 0)) as target_val_nop,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '12', qty, 0)) as target_qty_des,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '12', x.value, 0)) as target_val_des";
				$str_sql = $str_sql . " from sellingout_target x";
				$str_sql = $str_sql . " left join area y on x.area = y.area"; 
				$str_sql = $str_sql . " where x.tahun = '" . $year . "'";
				$str_sql = $str_sql . " group by x.item_code) c on a.item_code = c.item_code";

				$str_sql = $str_sql . " left join";
				$str_sql = $str_sql . " (select distinct x.principal, x.area, x.item_code,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '1', qty, 0)) as stok_qty_jan,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '1', x.value, 0)) as stok_val_jan,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '2', qty, 0)) as stok_qty_feb,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '2', x.value, 0)) as stok_val_feb,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '3', qty, 0)) as stok_qty_mar,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '3', x.value, 0)) as stok_val_mar,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '4', qty, 0)) as stok_qty_apr,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '4', x.value, 0)) as stok_val_apr,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '5', qty, 0)) as stok_qty_mei,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '5', x.value, 0)) as stok_val_mei,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '6', qty, 0)) as stok_qty_jun,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '6', x.value, 0)) as stok_val_jun,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '7', qty, 0)) as stok_qty_jul,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '7', x.value, 0)) as stok_val_jul,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '8', qty, 0)) as stok_qty_agu,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '8', x.value, 0)) as stok_val_agu,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '9', qty, 0)) as stok_qty_sep,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '9', x.value, 0)) as stok_val_sep,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '10', qty, 0)) as stok_qty_okt,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '10', x.value, 0)) as stok_val_okt,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '11', qty, 0)) as stok_qty_nop,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '11', x.value, 0)) as stok_val_nop,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '12', qty, 0)) as stok_qty_des,";
				$str_sql = $str_sql . " sum( if( CONVERT(x.bulan, SIGNED INTEGER) = '12', x.value, 0)) as stok_val_des";
				$str_sql = $str_sql . " from stok x ";
				$str_sql = $str_sql . " left join area y on x.area = y.area";
				$str_sql = $str_sql . " where x.tahun = '" . $year . "'";
				$str_sql = $str_sql . " group by x.principal, x.area, x.item_code) d on a.item_code = d.item_code";
			}

		}

		$str_sql = $str_sql . " inner join principal e on a.principal = e.principal";
		$str_sql = $str_sql . " inner join sku_group f on a.item_group = f.item_group";
		$str_sql = $str_sql . " inner join sku_category g on a.item_category = g.item_category";
		$str_sql = $str_sql . " group by a.principal, a.item_group, a.item_code";
		$str_sql = $str_sql . " order by e.id, g.id, a.id";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

