			$str_sql = $str_sql . " and aa.principal = '" . $principal . "'";
		}
		$str_sql = $str_sql . " group by aa.salesman, aa.item_code) a";
		$str_sql = $str_sql . " group by a.salesman) k on a.salesman = k.salesman";

		$str_sql = $str_sql . " left join";
		$str_sql = $str_sql . " (select a.salesman, sum(a.qty) as qty_11, sum(a.value_exc) as value_exc_11";
		$str_sql = $str_sql . " from";
		$str_sql = $str_sql . " (select aa.salesman, aa.item_code, sum(aa.qty) as qty, if(isnull(bb.price_exc), sum(aa.value_exc)/1000, (sum(aa.qty)*bb.price_exc)/1000) as value_exc";
		$str_sql = $str_sql . " from selling_out aa";
		$str_sql = $str_sql . " left join (select max(valid_from) as valid_from, item_code, price_exc from pricelist group by item_code) bb on aa.item_code = bb.item_code";
		$str_sql = $str_sql . " where year(aa.tanggal) = year(now()) and month(aa.tanggal) = '11'";
		if (isset($principal) and $principal != '')
		{
			$str_sql = $str_sql . " and aa.principal = '" . $principal . "'";
		}
		$str_sql = $str_sql . " group by aa.salesman, aa.item_code) a";
		$str_sql = $str_sql . " group by a.salesman) l on a.salesman = l.salesman";

		$str_sql = $str_sql . " left join";
		$str_sql = $str_sql . " (select a.salesman, sum(a.qty) as qty_12, sum(a.value_exc) as value_exc_12";
		$str_sql = $str_sql . " from";
		$str_sql = $str_sql . " (select aa.salesman, aa.item_code, sum(aa.qty) as qty, if(isnull(bb.price_exc), sum(aa.value_exc)/1000, (sum(aa.qty)*bb.price_exc)/1000) as value_exc";
		$str_sql = $str_sql . " from selling_out aa";
		$str_sql = $str_sql . " left join (select max(valid_from) as valid_from, item_code, price_exc from pricelist group by item_code) bb on aa.item_code = bb.item_code";
		$str_sql = $str_sql . " where year(aa.tanggal) = year(now()) and month(aa.tanggal) = '12'";
		if (isset($principal) and $principal != '')
		{
			$str_sql = $str_sql . " and aa.principal = '" . $principal . "'";
		}
		$str_sql = $str_sql . " group by aa.salesman, aa.item_code) a";
		$str_sql = $str_sql . " group by a.salesman) m on a.salesman = m.salesman";

		$str_sql = $str_sql . " left join";
		$str_sql = $str_sql . " (select a.salesman, sum(a.qty) as qty_total, sum(a.value_exc) as value_exc_total";
		$str_sql = $str_sql . " from";
		$str_sql = $str_sql . " (select aa.salesman, aa.item_code, sum(aa.qty) as qty, if(isnull(bb.price_exc), sum(aa.value_exc)/1000, (sum(aa.qty)*bb.price_exc)/1000) as value_exc";
		$str_sql = $str_sql . " from selling_out aa";
		$str_sql = $str_sql . " left join (select max(valid_from) as valid_from, item_code, price_exc from pricelist group by item_code) bb on aa.item_code = bb.item_code";
		$str_sql = $str_sql . " where year(aa.tanggal) = year(now())";
		if (isset($principal) and $principal != '')
		{
			$str_sql = $str_sql . " and aa.principal = '" . $principal . "'";
		}
		$str_sql = $str_sql . " group by aa.salesman, aa.item_code) a";
		$str_sql = $str_sql . " group by a.salesman) n on a.salesman = n.salesman";

		

		$str_sql = $str_sql . " inner join area o on a.area = o.area and a.region = o.region";

		$str_sql = $str_sql . " where not isnull(a.salesman)";

		if (isset($island) and $island != '')
		{
			$str_sql = $str_sql . " and o.island = '" . $island . "'";
		}

		if (isset($region) and $region != '')
		{
			$str_sql = $str_sql . " and a.region = '" . $region . "'";
		}

		if (isset($area) and $area != '')
		{
			$str_sql = $str_sql . " and a.area = '" . $area . "'";
		}

		// if (isset($principal) and $principal != '')
		// {
		// 	$str_sql = $str_sql . " and a.principal = '" . $principal . "'";
		// }

		$str_sql = $str_sql . " group by a.salesman";
		$str_sql = $str_sql . " order by a.salesman";

		Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

