	public function getSellingOut_Growth_Channel()
	{

		if (isset($_POST['by_area']))
		{
			$area = implode(',', $_POST['by_area']);
			$area = str_replace(",", "','", $area);;
		}
		elseif ($_SESSION['area'] != 'ALL')
		{
			$session_area = str_replace(", ", "','", $_SESSION['area']); 
			$area = $session_area;
		}

		if (isset($_POST['by_year']))
		{
			$year = $_POST['by_year'];
		}else
		{
			$year = date('Y');
		}

		$year_to = $year;
		$year_from = $year_to - 1;

		$str_sql = "SELECT c.id, c.channel, c.outlet_category,";
		$str_sql = $str_sql . " SUM(a.value_from) AS value_from, SUM(a.value_to) AS value_to,";
		$str_sql = $str_sql . " SUM(IF(a.value_from <> 0 AND a.value_to <> 0, a.value_to, 0)) AS value_exist,";
		$str_sql = $str_sql . " SUM(IF(a.value_from = 0 AND a.value_to <> 0 AND ISNULL(d.value_noo), a.value_to, 0)) AS value_add_sku,";
		$str_sql = $str_sql . " SUM(IF(ISNULL(d.value_noo), 0, d.value_noo)) as value_noo";
		$str_sql = $str_sql . " FROM (";
				$str_sql = $str_sql . " select so.id, so.outlet_type, so.big_code, so.cust_name, so.area, so.item_code,";
				$str_sql = $str_sql . " sum(if(year(so.tanggal) = '".$year_from."', so.value_exc, 0)) as 'value_from',";
				$str_sql = $str_sql . " sum(if(year(so.tanggal) = '".$year_to."', so.value_exc, 0)) as 'value_to',";
				$str_sql = $str_sql . " sum(so.value_exc) as value_total";
				$str_sql = $str_sql . " from selling_out so";
				$str_sql = $str_sql . " inner join channel c on so.outlet_type = c.outlet_type";
				$str_sql = $str_sql . " where so.principal = 'JORDAN'";
				if(isset($area) and $area != '')
				{
					$str_sql = $str_sql . " and so.area in ('".$area."')";
				}
				$str_sql = $str_sql . " and year(so.tanggal) in ('".$year_from."', '".$year_to."') and month(so.tanggal) in (select distinct month(tanggal) as bulan from selling_out where year(tanggal) = '".$year_to."') and so.value_exc <> 0";
				// $str_sql = $str_sql . " and year(so.tanggal) in ('".$year_from."', '".$year_to."') and so.value_exc <> 0";
				$str_sql = $str_sql . " group by so.outlet_type, so.big_code, so.item_code";
		$str_sql = $str_sql . " ) a";
		$str_sql = $str_sql . " INNER JOIN sku b on a.item_code = b.item_code";
		$str_sql = $str_sql . " RIGHT JOIN channel c on a.outlet_type = c.outlet_type";
		$str_sql = $str_sql . " LEFT JOIN (";
					$str_sql = $str_sql . " select so.id, so.outlet_type, so.big_code, so.item_code,";
					$str_sql = $str_sql . " sum(so.value_exc) as value_noo";
					$str_sql = $str_sql . " from selling_out so";
					$str_sql = $str_sql . " where so.principal = 'JORDAN'";
					if(isset($area) and $area != '')
					{
						$str_sql = $str_sql . " and so.area in ('".$area."')";
					}
					$str_sql = $str_sql . " and year(so.tanggal) in ('".$year_to."')";
					$str_sql = $str_sql . " and so.big_code not in (";
											$str_sql = $str_sql . " select distinct big_code";
											$str_sql = $str_sql . " from selling_out";
											$str_sql = $str_sql . " where principal = 'JORDAN'"; 
											if(isset($area) and $area != '')
											{
												$str_sql = $str_sql . " and area in ('".$area."')";
											}
											$str_sql = $str_sql . " and year(tanggal) = '".$year_from."'";
											$str_sql = $str_sql . " and month(tanggal) in (select distinct month(tanggal) as bulan from selling_out where year(tanggal) = '".$year_to."') and not isnull(big_code)";
											// $str_sql = $str_sql . " and not isnull(big_code)";
											$str_sql = $str_sql . " )";
					$str_sql = $str_sql . " group by so.outlet_type, so.big_code, so.item_code";
					$str_sql = $str_sql . " ) d ON a.outlet_type = d.outlet_type AND a.big_code = d.big_code AND a.item_code = d.item_code";
		$str_sql = $str_sql . " WHERE c.channel <> 'DISTRIBUTOR'";
		$str_sql = $str_sql . " GROUP BY c.outlet_category";
		$str_sql = $str_sql . " ORDER BY c.id;";

		// Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

	public function getSellingOut_Growth_Channel2()
	{
		if(isset($_POST['by_principal']))
		{
			$principal = $_POST['by_principal'];
		}else
		{
			$principal = "JORDAN";
		}

		if (isset($_POST['by_area']))
		{
			$area = implode(',', $_POST['by_area']);
			$area = str_replace(",", "','", $area);;
		}
		elseif ($_SESSION['area'] != 'ALL')
		{
			$session_area = str_replace(", ", "','", $_SESSION['area']); 
			$area = $session_area;
		}

		if(isset($_POST['by_month1']))
		{
			$month1 = $_POST['by_month1'];
		}else
		{
			$month1 = 1;
		}

		if(isset($_POST['by_month2']))
		{
			$month2 = $_POST['by_month2'];
		}else
		{
			$get['period_si'] = $this->getMonth_SO();
			$month2 = $get['period_si']['to_month'];
		}

		if (isset($_POST['by_year']))
		{
			$year = $_POST['by_year'];
		}else
		{
			$year = date('Y');
		}

		$year_to = $year;
		$year_from = $year_to - 1;

		$str_sql = "SELECT c.id, c.channel, c.outlet_category, c.outlet_type,";
		$str_sql = $str_sql . " SUM(a.value_from) AS value_from, SUM(a.value_to) AS value_to,";
		$str_sql = $str_sql . " SUM(IF(ISNULL(d.value_to), 0, d.value_to)) AS value_exist,";
