		$str_sql = $str_sql . " INNER JOIN sku b on a.item_code = b.item_code";
		$str_sql = $str_sql . " RIGHT JOIN channel c on a.outlet_type = c.outlet_type";
		$str_sql = $str_sql . " LEFT JOIN (";
					$str_sql = $str_sql . " select so_to.* from";
						$str_sql = $str_sql . " (";
						$str_sql = $str_sql . " select so.id, so.outlet_type, so.big_code, so.cust_name, so.area, so.item_code,";
						$str_sql = $str_sql . " sum(so.value_exc) as value_to";
						$str_sql = $str_sql . " from selling_out so";
						$str_sql = $str_sql . " inner join channel c on so.outlet_type = c.outlet_type";
						$str_sql = $str_sql . " where so.principal = '".$principal."'";
						if(isset($area) and $area != '')
						{
							$str_sql = $str_sql . " and so.area in ('".$area."')";
						}
						$str_sql = $str_sql . " and year(so.tanggal) in ('".$year_to."')";
						$str_sql = $str_sql . " and (month(so.tanggal) between '".$month1."' and '".$month2."')";
						$str_sql = $str_sql . " and so.value_exc <> 0";
						$str_sql = $str_sql . " group by so.outlet_type, so.big_code, so.item_code ";
						$str_sql = $str_sql . " ) so_to";
						$str_sql = $str_sql . " inner join";
						$str_sql = $str_sql . " (";
						$str_sql = $str_sql . " select so.id, so.outlet_type, so.big_code, so.cust_name, so.area, so.item_code,";
						$str_sql = $str_sql . " sum(so.value_exc) as value_to";
						$str_sql = $str_sql . " from selling_out so";
						$str_sql = $str_sql . " inner join channel c on so.outlet_type = c.outlet_type";
						$str_sql = $str_sql . " where so.principal = '".$principal."'";
						if(isset($area) and $area != '')
						{
							$str_sql = $str_sql . " and so.area in ('".$area."')";
						}
						$str_sql = $str_sql . " and year(so.tanggal) <= '".$year_from."'";
						// $str_sql = $str_sql . " and month(so.tanggal) in (select distinct month(tanggal) as bulan from selling_out where year(tanggal) = '".$year_to."') and not isnull(so.big_code)";
						$str_sql = $str_sql . " and not isnull(so.big_code)";
						$str_sql = $str_sql . " and so.value_exc <> 0";
						$str_sql = $str_sql . " group by so.outlet_type, so.big_code, so.item_code ";
						$str_sql = $str_sql . " ) so_from on so_to.outlet_type = so_from.outlet_type and so_to.big_code = so_from.big_code and so_to.item_code = so_from.item_code";
					$str_sql = $str_sql . " ) d ON a.outlet_type = d.outlet_type AND a.big_code = d.big_code AND a.item_code = d.item_code";
		$str_sql = $str_sql . " LEFT JOIN (";
					$str_sql = $str_sql . " select so.id, so.outlet_type, so.big_code, so.item_code,";
					$str_sql = $str_sql . " sum(so.value_exc) as value_noo";
					$str_sql = $str_sql . " from selling_out so";
					$str_sql = $str_sql . " where so.principal = '".$principal."'";
					if(isset($area) and $area != '')
					{
						$str_sql = $str_sql . " and so.area in ('".$area."')";
					}
					$str_sql = $str_sql . " and year(so.tanggal) in ('".$year_to."')";
					$str_sql = $str_sql . " and (month(so.tanggal) between '".$month1."' and '".$month2."')";
					$str_sql = $str_sql . " and so.big_code not in (";
											$str_sql = $str_sql . " select distinct big_code";
											$str_sql = $str_sql . " from selling_out";
											$str_sql = $str_sql . " where principal = '".$principal."'"; 
											if(isset($area) and $area != '')
											{
												$str_sql = $str_sql . " and area in ('".$area."')";
											}
											$str_sql = $str_sql . " and year(tanggal) <= '".$year_from."'";
											// $str_sql = $str_sql . " and month(tanggal) in (select distinct month(tanggal) as bulan from selling_out where year(tanggal) = '".$year_to."') and not isnull(big_code)";
											$str_sql = $str_sql . " )";
					$str_sql = $str_sql . " group by so.outlet_type, so.big_code, so.item_code";
					$str_sql = $str_sql . " ) e ON a.outlet_type = e.outlet_type AND a.big_code = e.big_code AND a.item_code = e.item_code";
		$str_sql = $str_sql . " INNER JOIN sku_category f ON b.item_category = f.item_category";
		$str_sql = $str_sql . " GROUP BY b.item_category";
		$str_sql = $str_sql . " ORDER BY f.id";


		// Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

	public function getAO_Lord_last($data)
	{
		$principal = "LORD";
		$str_sql = "SELECT distinct a.id, a.channel, a.desc_type, a.outlet_type, b.RO, c.DISTR, (c.DISTR/b.RO)*100 as '%', d.AO, (d.AO/c.DISTR)*100 as '%AO'";
		$str_sql = $str_sql . " from channel a";
		$str_sql = $str_sql . " left join (";
					$str_sql = $str_sql . " select c.outlet_type, sum(a.total_outlet) as ro";
					$str_sql = $str_sql . " from outlet a";
					$str_sql = $str_sql . " left join distributor b on a.dist_code = b.cust_code and a.area = b.area and b.is_active = 1";
					$str_sql = $str_sql . " right join channel c on a.outlet_type = c.outlet_type";
					$str_sql = $str_sql . " inner join area d on a.area = d.area and b.area = d.area";
					$str_sql = $str_sql . " group by a.outlet_type";
					$str_sql = $str_sql . " order by c.id";
					$str_sql = $str_sql . " ) b on a.outlet_type = b.outlet_type";
		$str_sql = $str_sql . " left join (select tbl.outlet_type, sum(tbl.TOTAL) as DISTR";
					$str_sql = $str_sql . " from (select x.outlet_type, sum(distinct z.outlet_count) as TOTAL";
							$str_sql = $str_sql . " from selling_out x";
							$str_sql = $str_sql . " left join area y on x.area = y.area";
							$str_sql = $str_sql . " inner join dc z on x.cust_code = z.outlet_code";
							$str_sql = $str_sql . " where x.principal = :principal and x.inv_status = 'INVOICE'";
							$str_sql = $str_sql . " and x.tanggal between DATE_SUB(concat('" . $data['year'] . "', '-','" . $data['to_month'] . "','-1'), INTERVAL 12 month) and LAST_DAY(concat('" . $data['year'] . "', '-','" . $data['to_month'] . "','-1'))";
							$str_sql = $str_sql . " group by x.outlet_type";
							$str_sql = $str_sql . " UNION ALL";
							$str_sql = $str_sql . " select x.outlet_type, count(distinct x.cust_code) as TOTAL";
							$str_sql = $str_sql . " from selling_out x";
							$str_sql = $str_sql . " left join area y on x.area = y.area";
							$str_sql = $str_sql . " where x.cust_code not in (select outlet_code from dc)";
							$str_sql = $str_sql . " and x.principal = :principal and x.inv_status = 'INVOICE'";
							$str_sql = $str_sql . " and x.tanggal between DATE_SUB(concat('" . $data['year'] . "', '-','" . $data['to_month'] . "','-1'), INTERVAL 12 month) and LAST_DAY(concat('" . $data['year'] . "', '-','" . $data['to_month'] . "','-1'))";
							$str_sql = $str_sql . " group by x.outlet_type) tbl";
							$str_sql = $str_sql . " group by tbl.outlet_type) c on a.outlet_type = c.outlet_type";
		$str_sql = $str_sql . " left join (select tbl.outlet_type, sum(tbl.TOTAL) as AO";
					$str_sql = $str_sql . " from (select x.outlet_type, sum(distinct z.outlet_count) as TOTAL";
							$str_sql = $str_sql . " from selling_out x";
							$str_sql = $str_sql . " left join area y on x.area = y.area";
							$str_sql = $str_sql . " inner join dc z on x.cust_code = z.outlet_code";
							$str_sql = $str_sql . " where x.principal = :principal and x.inv_status = 'INVOICE'";
							$str_sql = $str_sql . " and month(x.tanggal) = '" . $data['to_month'] . "' and year(x.tanggal) = '" . $data['year'] . "'";
							$str_sql = $str_sql . " group by x.outlet_type";
							$str_sql = $str_sql . " UNION ALL";
							$str_sql = $str_sql . " select x.outlet_type, count(distinct x.cust_code) as TOTAL";
							$str_sql = $str_sql . " from selling_out x";
							$str_sql = $str_sql . " left join area y on x.area = y.area";
							$str_sql = $str_sql . " where x.cust_code not in (select outlet_code from dc)";
							$str_sql = $str_sql . " and x.principal = :principal and x.inv_status = 'INVOICE'";
							$str_sql = $str_sql . " and month(x.tanggal) = '" . $data['to_month'] . "' and year(x.tanggal) = '" . $data['year'] . "'";
							$str_sql = $str_sql . " group by x.outlet_type) tbl";
							$str_sql = $str_sql . " group by tbl.outlet_type) d on a.outlet_type = d.outlet_type";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		if (isset($principal) and $principal != '')
		{
			$this->db->bind('principal', $principal);
		}

		return $this->db->resultSet();
	}

