	public function getAO_Lord()
	{
		if (isset($_POST['by_region']))
		{
			$region = $_POST['by_region'];
		}
		if (isset($_POST['by_area']))
		{
			$area = $_POST['by_area'];
		}
		if (isset($_POST['by_island']))
		{
			$island = $_POST['by_island'];
		}
		if(isset($_POST['by_month1']))
		{
			$month1 = $_POST['by_month1'];
		}else
		{
			$month1 = date('m');
		}
		if(isset($_POST['by_month2']))
		{
			$month2 = $_POST['by_month2'];
		}else
		{
			$month2 = date('m');
		}
		if(isset($_POST['by_year']))
		{
			$year = $_POST['by_year'];
		}else
		{
			$year = date('Y');
		}

		//$fromdate = '-' .$month. '-1';
		////$todate = '-' .$month. '-31';

		$str_sql = "SELECT distinct a.id, a.channel, a.desc_type, a.outlet_type, b.RO, c.DISTR as d1, (c.DISTR/b.RO)*100 as '%1', d.DISTR as d2, (d.DISTR/b.RO)*100 as '%2', e.DISTR as d3, (e.DISTR/b.RO)*100 as '%3',";
		$str_sql = $str_sql . " f.DISTR as d4, (f.DISTR/b.RO)*100 as '%4', g.DISTR as d5, (g.DISTR/b.RO)*100 as '%5', h.DISTR as d6, (h.DISTR/b.RO)*100 as '%6', i.DISTR as d7, (i.DISTR/b.RO)*100 as '%7',";
		$str_sql = $str_sql . " j.DISTR as d8, (j.DISTR/b.RO)*100 as '%8', k.DISTR as d9, (k.DISTR/b.RO)*100 as '%9', l.DISTR as d10, (l.DISTR/b.RO)*100 as '%10', m.DISTR as d11, (m.DISTR/b.RO)*100 as '%11',";
		$str_sql = $str_sql . " n.DISTR as d12, (n.DISTR/b.RO)*100 as '%12', o.DISTR as d13, (o.DISTR/b.RO)*100 as '%13', p.DISTR as d14, (p.DISTR/b.RO)*100 as '%14', q.DISTR as d15, (q.DISTR/b.RO)*100 as '%15',";
		$str_sql = $str_sql . " r.DISTR as d16, (r.DISTR/b.RO)*100 as '%16', s.DISTR as d17, (s.DISTR/b.RO)*100 as '%17', t.DISTR as d18, (t.DISTR/b.RO)*100 as '%18', u.DISTR as dtotal, (u.DISTR/b.RO)*100 as '%total'";
		$str_sql = $str_sql . " from channel a";

		if (isset($island) and isset($area) and isset($region) and $island != '' and $area != '' and $region != '')
		{
			
			$str_sql = $str_sql . " left join (select x.outlet_type, sum(x.ro) as ro from ro x left join area y on x.area = y.area where x.principal = 'LORD' and y.island = '" . $island . "' and x.area = '" . $area . "' and y.region = '" . $region . "' and (x.bulan between '" .$month1. "' and '" .$month2. "') and x.tahun = '" . $year . "' group by x.outlet_type) b on a.outlet_type = b.outlet_type";
