	public function setSOContribution()
	{
		if (isset($_POST['by_region']))
		{
			$region = $_POST['by_region'];
		}
		if (isset($_POST['by_area']))
		{
			$area = $_POST['by_area'];
		}
		if (isset($_POST['by_island']))
		{
			$island = $_POST['by_island'];
		}
		if(isset($_POST['by_month1']))
		{
			$month1 = $_POST['by_month1'];
		}else
		{
			$month1 = date('m');
		}
		if(isset($_POST['by_month2']))
		{
			$month2 = $_POST['by_month2'];
		}else
		{
			$month2 = date('m');
		}
		if(isset($_POST['by_year']))
		{
			$year = $_POST['by_year'];
		}else
		{
			$year = date('Y');
		}

		$str_sql = "DROP TABLE IF EXISTS temp_so_contribution;";
		$str_sql = $str_sql . " create table temp_so_contribution";
		$str_sql = $str_sql . " select a.id, a.channel, a.desc_type, a.outlet_type, b.id as item_id, b.item_group, b.item_code, b.qty, b.val";
		$str_sql = $str_sql . " from channel a";
		$str_sql = $str_sql . " left join (";
		$str_sql = $str_sql . " select y.outlet_type, x.id, x.principal, x.item_group, x.item_code, y.qty, y.val";
		$str_sql = $str_sql . " from sku x";
		$str_sql = $str_sql . " left join (select aa.outlet_type, aa.item_code, sum(aa.qty) as qty, sum(aa.value_exc) as val";
		$str_sql = $str_sql . " from selling_out aa";
		$str_sql = $str_sql . " left join area bb on aa.area = bb.area and (month(aa.tanggal) between '" .$month1. "' and '" .$month2. "') and year(aa.tanggal) = '" . $year . "'";

		if (isset($island) and $island != '')
		{
			$str_sql = $str_sql . " and bb.island = '" . $island . "'";
		}

		if (isset($region) and $region != '')
		{
			$str_sql = $str_sql . " and aa.region = '" . $region . "'";
		}

		if (isset($area) and $area != '')
		{
			$str_sql = $str_sql . " and aa.area = '" . $area . "'";
		}

		$str_sql = $str_sql . " group by outlet_type, item_code) y on x.item_code = y.item_code";
		$str_sql = $str_sql . " group by x.id, x.principal, x.item_code, y.outlet_type";
		$str_sql = $str_sql . " order by x.id, x.principal, x.item_code, y.outlet_type) b on a.outlet_type = b.outlet_type";
		$str_sql = $str_sql . " group by a.id, b.outlet_type, b.item_code";
		$str_sql = $str_sql . " order by a.id, b.outlet_type, b.id, b.item_code";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		$this->db->execute();
		return $this->db->rowCount();
	}

