	public function getAO_jordan1_export($data)
	{
		if (isset($data['region']))
		{
			$region = $data['region'];
		}
		if (isset($data['area']))
		{
			$area = $data['area'];
		}
		if (isset($data['island']))
		{
			$island = $data['island'];
		}
		if(isset($data['month1']))
		{
			$month1 = $data['month1'];
		}else
		{
			$month1 = date('m');
		}
		if(isset($data['month2']))
		{
			$month2 = $data['month2'];
		}else
		{
			$month2 = date('m');
		}
		if(isset($data['year']))
		{
			$year = $data['year'];
		}else
		{
			$year = date('Y');
		}

		//$fromdate = '-' .$month. '-1';
		////$todate = '-' .$month. '-31';
		$str_sql = "DROP TABLE IF EXISTS temp_ao_jordan1;";
		$str_sql = $str_sql . " create table temp_ao_jordan1";
		//$str_sql = "INSERT INTO temp_ao_jordan1";
		$str_sql = $str_sql . " SELECT distinct a.id as id, a.channel as channel, a.desc_type as desc_type, a.outlet_type as outlet_type, b.RO as RO, c.DISTR as d1, (c.DISTR/b.RO)*100 as '%1', d.DISTR as d2, (d.DISTR/b.RO)*100 as '%2', e.DISTR as d3, (e.DISTR/b.RO)*100 as '%3',";
		$str_sql = $str_sql . " f.DISTR as d4, (f.DISTR/b.RO)*100 as '%4', g.DISTR as d5, (g.DISTR/b.RO)*100 as '%5', h.DISTR as d6, (h.DISTR/b.RO)*100 as '%6', i.DISTR as d7, (i.DISTR/b.RO)*100 as '%7',";
