	public function getDistr_summary()
	{

		$get['period_so'] = $this->getMonth_SO2($_POST['by_year']);
		$month_so = $get['period_so']['to_month'];
		$year_so = $get['period_so']['year'];
		
		if(isset($_POST['by_principal']))
		{
			$principal = $_POST['by_principal'];
		}else
		{
			$principal = "JORDAN";
		}
		if (isset($_POST['by_area']))
		{
			$area = implode(',', $_POST['by_area']);
			$area = str_replace(",", "','", $area);;
		}
		elseif ($_SESSION['area'] != 'ALL')
		{
			$session_area = str_replace(", ", "','", $_SESSION['area']); 
			$area = $session_area;
		}
		else
		{
			$area = "";
		}
		if(isset($_POST['by_year']))
		{
			$year = $_POST['by_year'];
		}else
		{
			$year = $year_so;
		}

		$current_year = date('Y');
		$old_year = (int)$year - 1;
		
		$str_sql = " SELECT DISTINCT a.id as id, a.channel as channel, a.desc_type as desc_type, a.outlet_type as outlet_type,";
		$str_sql = $str_sql . " b.RO_1, c.DIST_1, c.AO_1, b.RO_2, c.DIST_2, c.AO_2, b.RO_3, c.DIST_3, c.AO_3, b.RO_4, c.DIST_4, c.AO_4, b.RO_5, c.DIST_5, c.AO_5, b.RO_6, c.DIST_6, c.AO_6,";
		$str_sql = $str_sql . " b.RO_7, c.DIST_7, c.AO_7, b.RO_8, c.DIST_8, c.AO_8, b.RO_9, c.DIST_9, c.AO_9, b.RO_10, c.DIST_10, c.AO_10, b.RO_11, c.DIST_11, c.AO_11, b.RO_12, c.DIST_12, c.AO_12,";
		$str_sql = $str_sql . " b.RO_12_old, c.DIST_12_old, c.AO_12_old";
		$str_sql = $str_sql . " FROM channel a";
		$str_sql = $str_sql . " LEFT JOIN ( select o.outlet_type, sum(o.RO_1) as RO_1, sum(o.RO_2) as RO_2, sum(o.RO_3) as RO_3, sum(o.RO_4) as RO_4, sum(o.RO_5) as RO_5, sum(o.RO_6) as RO_6,";
					$str_sql = $str_sql . " sum(o.RO_7) as RO_7, sum(o.RO_8) as RO_8, sum(o.RO_9) as RO_9, sum(o.RO_10) as RO_10, sum(o.RO_11) as RO_11, sum(o.RO_12) as RO_12, sum(o.RO_12_old) as RO_12_old";
					$str_sql = $str_sql . " from (";
							$str_sql = $str_sql . " select c.outlet_type, a.big_code,";
					for($i=1;$i<=12;$i++)
					{
						if($month_so >= $i)
						{
							$str_sql = $str_sql . " max( if(a.register_date <= last_day('".$year."-".$i."-01'), a.total_outlet, 0)) AS RO_".$i.",";
						}
						else
						{
							$str_sql = $str_sql . " 0 AS RO_".$i.",";
						}
						
					}
							$str_sql = $str_sql . " max( if(a.register_date <= last_day('".$old_year."-12-01'), a.total_outlet, 0)) AS RO_12_old";
							$str_sql = $str_sql . " from outlet a";
							$str_sql = $str_sql . " inner join distributor b on a.dist_code = b.cust_code and a.area = b.area";
							$str_sql = $str_sql . " inner join channel c on a.outlet_type = c.outlet_type";
							$str_sql = $str_sql . " inner join area d on a.area = d.area";
							if($area !== 'ALL' and $area !== "")
							{
								$str_sql = $str_sql . " where a.area in ('".$area."')";
							}
							$str_sql = $str_sql . " group by a.outlet_type, a.big_code, a.area";
							$str_sql = $str_sql . " order by a.big_code ) o";
					$str_sql = $str_sql . " group by outlet_type ) b on a.outlet_type = b.outlet_type";
		$str_sql = $str_sql . " LEFT JOIN (";
					$str_sql = $str_sql . " select dist.outlet_type,";
					$str_sql = $str_sql . " sum(dist.DIST_1) as DIST_1, sum(dist.DIST_2) as DIST_2, sum(dist.DIST_3) as DIST_3, sum(dist.DIST_4) as DIST_4, sum(dist.DIST_5) as DIST_5, sum(dist.DIST_6) as DIST_6,";
					$str_sql = $str_sql . " sum(dist.DIST_7) as DIST_7, sum(dist.DIST_8) as DIST_8, sum(dist.DIST_9) as DIST_9, sum(dist.DIST_10) as DIST_10, sum(dist.DIST_11) as DIST_11,  sum(dist.DIST_12) as DIST_12, sum(dist.DIST_12_old) as DIST_12_old,";
					$str_sql = $str_sql . " sum(dist.AO_1) as AO_1, sum(dist.AO_2) as AO_2, sum(dist.AO_3) as AO_3, sum(dist.AO_4) as AO_4, sum(dist.AO_5) as AO_5, sum(dist.AO_6) as AO_6,";
					$str_sql = $str_sql . " sum(dist.AO_7) as AO_7, sum(dist.AO_8) as AO_8, sum(dist.AO_9) as AO_9, sum(dist.AO_10) as AO_10, sum(dist.AO_11) as AO_11,  sum(dist.AO_12) as AO_12, sum(dist.AO_12_old) as AO_12_old";
