									$str_sql = $str_sql . " max(distinct if(month(x.tanggal) = '".$i."' and year(x.tanggal) = '".$year."', z.total_outlet, null )) as AO_".$i.",";
								}
								else
								{
									$str_sql = $str_sql . " max(distinct if(x.tanggal between DATE_SUB(concat('".$year."', '-','0','-1'), INTERVAL 11 month) and LAST_DAY(concat('".$year."', '-','0','-1')), z.total_outlet, null )) as DIST_".$i.",";
									$str_sql = $str_sql . " max(distinct if(month(x.tanggal) = '0' and year(x.tanggal) = '".$year."', z.total_outlet, null )) as AO_".$i.",";
								}
								
							}
							$str_sql = $str_sql . " max(distinct if(x.tanggal between DATE_SUB(concat('".$old_year."', '-','12','-1'), INTERVAL 11 month) and LAST_DAY(concat('".$old_year."', '-','12','-1')), z.total_outlet, null )) as DIST_12_old,";
							$str_sql = $str_sql . " max(distinct if(month(x.tanggal) = '12' and year(x.tanggal) = '".$old_year."', z.total_outlet, null )) as AO_12_old";
							$str_sql = $str_sql . " from selling_out x";
							$str_sql = $str_sql . " left join area y on x.area = y.area";
							$str_sql = $str_sql . " inner join outlet z on x.big_code = z.big_code and x.outlet_type = z.outlet_type and x.area = z.area and z.total_outlet >= 1";
							$str_sql = $str_sql . " where x.principal = '".$principal."'";
							if($area !== 'ALL' and $area !== "")
							{
