							$str_sql = $str_sql . " group by x.outlet_type, x.big_code, x.area ) dist";
					$str_sql = $str_sql . " group by dist.outlet_type) c on a.outlet_type = c.outlet_type";
		$str_sql = $str_sql . " WHERE a.outlet_type <> 'DIST'";
		$str_sql = $str_sql . " GROUP BY a.outlet_type";
		$str_sql = $str_sql . " ORDER BY a.id";
		
		// Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

