		$str_sql = $str_sql . " SELECT distinct a.id as id2, a.channel as channel2, a.desc_type as desc_type2, a.outlet_type as outlet_type2, b.RO as RO2, c.DISTR as d34, (c.DISTR/b.RO)*100 as '%34', d.DISTR as d35, (d.DISTR/b.RO)*100 as '%35', e.DISTR as d36, (e.DISTR/b.RO)*100 as '%36',";
