	public function getDistr_jordan()
	{
		$str_sql = "SELECT * from temp_distr_jordan1 a";
		$str_sql = $str_sql . " left join temp_distr_jordan2 b on a.id = b.id2 and a.channel = b.channel2 and a.desc_type = b.desc_type2 and a.outlet_type = b.outlet_type2 and a.RO = b.RO2";
		$str_sql = $str_sql . " order by a.id, a.channel, a.desc_type, a.outlet_type";

		////Flasher::setMessage('Berhasil',$str_sql,'success');

		$this->db->opendb();
		$this->db->query($str_sql);
		return $this->db->resultSet();
	}

